	/**
	 * Splits the quest-item entries into the two caches the lookup uses: the unconditional ones, and
	 * the ones gated on a quest being in progress.
	 *
	 * <p>Entries are keyed by item id when the codex gives a number and by lower-cased name
	 * otherwise, the same way {@link #parseList} does, so both spellings of an entry work. An entry
	 * whose quests are all unknown to this client is kept in the gated map with an empty list, which
	 * means "never allowed" rather than "always allowed" - a typo should not silently hand out a
	 * permanent exemption.
	 */
	private void parseQuestItems(List<ContentPack.QuestItem> entries)
	{
		questItemNames.clear();
		questItemIds.clear();
		questGatedNames.clear();
		questGatedIds.clear();

		for (ContentPack.QuestItem entry : entries)
		{
			if (entry == null || entry.item == null || entry.item.trim().isEmpty())
			{
				continue;
			}
			final String token = entry.item.trim();
			Integer id = null;
			try
			{
				id = Integer.valueOf(token);
			}
			catch (NumberFormatException e)
			{
				// a name, not an id
			}

			if (entry.unconditional())
			{
				if (id != null)
				{
					questItemIds.add(id);
				}
				else
				{
					questItemNames.add(token.toLowerCase(Locale.ROOT));
				}
				continue;
			}

			List<Quest> resolved = new ArrayList<>();
			for (String questName : entry.quests)
			{
				Quest q = questByName(questName);
				if (q != null)
				{
					resolved.add(q);
				}
				else if (questName != null && !questName.trim().isEmpty()
					&& unknownQuests.add(questName.trim().toLowerCase(Locale.ROOT)))
				{
					log.warn("[BATTLE-MAGE] Quest item '{}' names a quest this client does not know: {}",
						token, questName.trim());
				}
			}
			if (id != null)
			{
				questGatedIds.put(id, resolved);
			}
			else
			{
				questGatedNames.put(token.toLowerCase(Locale.ROOT), resolved);
			}
		}
		refreshQuestProgress();
		refreshMageArena2();
	}

	private void parseList(String raw, Set<String> names, Set<Integer> ids)
	{
		names.clear();
		ids.clear();
		for (String token : split(raw))
		{
			try
			{
				ids.add(Integer.parseInt(token));
			}
			catch (NumberFormatException e)
			{
				names.add(token.toLowerCase(Locale.ROOT));
			}
		}
	}

	/** Parses "name-or-id:delta[:effects]" entries into the spec-weapon delta and effect caches. */
	private void parseSpecWeapons(String raw)
	{
		parseEffectSpec(raw, specDeltaIds, specDeltaNames, specEffectIds, specEffectNames);
	}

	/** Parses "name-or-id:delta[:effects]" entries into the consumable delta and effect caches. */
	private void parseConsumables(String raw)
	{
		parseEffectSpec(raw, consumableDeltaIds, consumableDeltaNames, consumableEffectIds, consumableEffectNames);
	}

	/**
	 * Parses "weapon-or-id[:spell+spell]" entries into the sustained-freeze caches.
	 *
	 * <p>A weapon with no spells listed still sustains on its own melee attack, so an empty spell set
	 * is meaningful rather than a parse failure - it means "melee only".
	 */
	private void parseSustainedFreeze(String raw)
	{
		sustainSpellsByName.clear();
		sustainSpellsById.clear();
		for (String token : split(raw))
		{
			String[] parts = token.split(":", 2);
			String key = parts[0].trim();
			if (key.isEmpty())
			{
				continue;
			}
			Set<String> spells = new HashSet<>();
			if (parts.length > 1)
			{
				for (String sp : parts[1].split("\\+"))
				{
					String t = sp.trim();
					if (!t.isEmpty())
					{
						spells.add(t.toLowerCase(Locale.ROOT));
					}
				}
			}
			try
			{
				sustainSpellsById.put(Integer.valueOf(key.trim()), spells);
			}
			catch (NumberFormatException e)
			{
				sustainSpellsByName.put(key.toLowerCase(Locale.ROOT), spells);
			}
		}
	}

	/** Shared parser for "name-or-id:delta[:effects]" entries (used by spec weapons and consumables). */
	private void parseEffectSpec(String raw, Map<Integer, Integer> deltaIds, Map<String, Integer> deltaNames,
		Map<Integer, SpecEffect> effectIds, Map<String, SpecEffect> effectNames)
	{
		deltaNames.clear();
		deltaIds.clear();
		effectNames.clear();
		effectIds.clear();
		for (String token : split(raw))
		{
			String[] parts = token.split(":", 3);
			if (parts.length < 2)
			{
				continue;
			}
			String key = parts[0].trim();
			if (key.isEmpty())
			{
				continue;
			}
			int delta;
			try
			{
				delta = Integer.parseInt(parts[1].trim());
			}
			catch (NumberFormatException e)
			{
				continue;
			}
			SpecEffect fx = parts.length >= 3 ? parseSpecEffect(parts[2].trim()) : null;
			Integer id = null;
			try
			{
				id = Integer.parseInt(key);
			}
			catch (NumberFormatException ignored)
			{
				// it's a name
			}
			if (id != null)
			{
				deltaIds.put(id, delta);
				if (fx != null && fx.any())
				{
					effectIds.put(id, fx);
				}
			}
			else
			{
				String lower = key.toLowerCase(Locale.ROOT);
				deltaNames.put(lower, delta);
				if (fx != null && fx.any())
				{
					effectNames.put(lower, fx);
				}
			}
		}
	}

	/** Parses effect codes like "F5", "O3a", "D10s" joined with '+'. */
	/** A whole number above zero, or 0 for anything else. */
	private static int parsePositive(String raw)
	{
		try
		{
			int n = Integer.parseInt(raw.trim());
			return Math.max(0, n);
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	private SpecEffect parseSpecEffect(String raw)
	{
		SpecEffect fx = new SpecEffect();
		if (raw == null || raw.isEmpty())
		{
			return fx;
		}
		for (String codeRaw : raw.split("\\+"))
		{
			String code = codeRaw.trim();
			if (code.length() < 2)
			{
				continue;
			}
			char type = Character.toUpperCase(code.charAt(0));
			String rest = code.substring(1).trim();

			// clear tokens: CO clears an active overload, CD clears an active depletion (both reset to 50%)
			String upper = code.toUpperCase(Locale.ROOT);
			if (upper.equals("CO"))
			{
				fx.clearOverload = true;
				continue;
			}
			if (upper.equals("CD"))
			{
				fx.clearDepletion = true;
				continue;
			}
			// KO: critical overload. DP: straight into depletion, breaking any depletion immunity.
			if (upper.equals("KO"))
			{
				fx.criticalOverload = true;
				continue;
			}
			if (upper.equals("DP"))
			{
				fx.forceDepletion = true;
				continue;
			}
			// G<pct>/<n> and S<pct>/<n>: PKP gained / spent at pct percent for n seconds.
			if ((type == 'G' || type == 'S') && rest.indexOf('/') > 0)
			{
				int slash = rest.indexOf('/');
				int pct = parsePositive(rest.substring(0, slash));
				int secs = parsePositive(rest.substring(slash + 1).toLowerCase(Locale.ROOT).replace("s", ""));
				if (pct > 0 && secs > 0)
				{
					if (type == 'G')
					{
						fx.gainPercent = pct;
						fx.gainSeconds = secs;
					}
					else
					{
						fx.spendPercent = pct;
						fx.spendSeconds = secs;
					}
				}
				continue;
			}

			// The gamble: R<amount> is a coin flip for plus-or-minus that amount, R<gain>/<loss> an
			// uneven one. Parsed here, ahead of the a/s suffix handling below, because its payload is
			// one or two plain numbers and a trailing 's' would otherwise be eaten as "seconds".
			//
			// Both halves are magnitudes, so they are written unsigned: R50/25 is "+50 or -25", never
			// "-50 or 25". A half that will not parse, or is not positive, makes the whole token
			// nothing rather than half a gamble - a typo must not leave a weapon that only ever loses.
			// X<secs>/<every>: the Poison chalice's chaos - see SpecEffect#chaosSeconds
			if (type == 'X' && rest.indexOf('/') > 0)
			{
				int slash = rest.indexOf('/');
				int secs = parsePositive(rest.substring(0, slash));
				int every = parsePositive(rest.substring(slash + 1).toLowerCase(Locale.ROOT).replace("s", ""));
				if (secs > 0 && every > 0)
				{
					fx.chaosSeconds = secs;
					fx.chaosEvery = every;
				}
				continue;
			}
			if (type == 'R')
			{
				int slash = rest.indexOf('/');
				String gainPart = slash < 0 ? rest : rest.substring(0, slash);
				String lossPart = slash < 0 ? rest : rest.substring(slash + 1);
				int gain;
				int loss;
				try
				{
					gain = Integer.parseInt(gainPart.trim());
					loss = Integer.parseInt(lossPart.trim());
				}
				catch (NumberFormatException e)
				{
					continue;
				}
				// The GAIN must be positive: a gamble with nothing to win is a weapon that only ever
				// loses, which is what a typo looks like, so it voids the whole token. A zero LOSS is
				// a real thing to want, though - "R33/0" is a free gamble, +33 or nothing - so zero is
				// allowed on that side alone.
				if (gain <= 0 || loss < 0)
				{
					continue;
				}
				// Two R codes on one weapon take the bigger of each side rather than stacking, the
				// same way the freeze and immunity codes do.
				fx.randomGain = Math.max(fx.randomGain, gain);
				fx.randomLoss = Math.max(fx.randomLoss, loss);
				continue;
			}


			boolean attacks = rest.toLowerCase(Locale.ROOT).endsWith("a");
			boolean secs = rest.toLowerCase(Locale.ROOT).endsWith("s");
			String num = (attacks || secs) ? rest.substring(0, rest.length() - 1) : rest;
			int n;
			try
			{
				n = Integer.parseInt(num.trim());
			}
			catch (NumberFormatException e)
			{
				continue;
			}
			if (n <= 0)
			{
				continue;
			}
			switch (type)
			{
				case 'F':
					if (attacks)
					{
						fx.freezeAttacks = n;
					}
					else
					{
						fx.freezeSeconds = n;
					}
					break;
				case 'O':
					if (attacks)
					{
						fx.overloadImmuneAttacks = n;
					}
					else
					{
						fx.overloadImmuneSeconds = n;
					}
					break;
				case 'D':
					if (attacks)
					{
						fx.depletionImmuneAttacks = n;
					}
					else
					{
						fx.depletionImmuneSeconds = n;
					}
					break;
				case 'Z':
					fx.freezeNowSeconds = n;
					break;
				default:
					break;
			}
		}
		return fx;
	}

	private void parseNameSet(String raw, Set<String> names)
	{
		names.clear();
		for (String token : split(raw))
		{
			names.add(token.toLowerCase(Locale.ROOT));
		}
	}

	private void parseIntSet(String raw, Set<Integer> out)
	{
		out.clear();
		for (String token : split(raw))
		{
			try
			{
				out.add(Integer.parseInt(token));
			}
			catch (NumberFormatException ignored)
			{
				// skip
			}
		}
	}

	private void parsePairs(String raw, Map<String, Integer> names, Map<Integer, Integer> ids)
	{
		names.clear();
		ids.clear();
		for (String token : split(raw))
		{
			int colon = token.lastIndexOf(':');
			if (colon < 0)
			{
				continue;
			}
			String key = token.substring(0, colon).trim();
			String valStr = token.substring(colon + 1).trim();
			if (key.isEmpty())
			{
				continue;
			}
			int amount;
			try
			{
				amount = Integer.parseInt(valStr);
			}
			catch (NumberFormatException e)
			{
				continue;
			}
			try
			{
				ids.put(Integer.parseInt(key), amount);
			}
			catch (NumberFormatException e)
			{
				names.put(key.toLowerCase(Locale.ROOT), amount);
			}
		}
	}

	private static List<String> split(String raw)
	{
		List<String> out = new ArrayList<>();
		if (raw == null)
		{
			return out;
		}
		for (String t : raw.split(","))
		{
			String s = t.trim();
			if (!s.isEmpty())
			{
				out.add(s);
			}
		}
		return out;
	}
}

package com.battlemage;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Stroke;
import java.awt.event.MouseEvent;
import java.awt.geom.Area;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The "how do I start?" signpost: a flat amber exclamation point in an open amber ring, in the
 * bottom left of the game view, shown whenever the plugin is on but no god is sworn. It lightens a
 * few shades while the mouse is over it.
 *
 * <p>Clicking it opens a box above it saying where to go; clicking the ring or the box again closes
 * it. The first two openings give the short hint; from the third on it adds the exact spot. The
 * count is saved, so it carries over between sessions. It steps aside while the oath pop-up is open and disappears for good the moment
 * a god is sworn (it comes back if the faction is denounced). Like any overlay it can be Alt-dragged
 * somewhere else.
 */
@Singleton
class BeginHintOverlay extends Overlay
{
	private static final Color AMBER = new Color(0xFF, 0xB9, 0x11);
	/** A few shades lighter, for while the mouse is over it. */
	private static final Color AMBER_HOVER = new Color(0xFF, 0xD2, 0x66);
	/** A soft drop shadow, as the game gives its own icons, so it holds up on bright ground. */
	private static final Color SHADOW = new Color(0, 0, 0, 90);
	private static final Color BOX = new Color(18, 14, 10, 235);
	private static final Color BOX_TEXT = new Color(255, 236, 214);

	/** The ring's outer diameter, and a small margin around it for the shadow. */
	private static final int RING_D = 30;
	private static final int GLOW_PAD = 2;
	private static final int BUBBLE_D = RING_D + GLOW_PAD * 2;
	private static final int BUBBLE_H = BUBBLE_D;

	/** How many times the box has been opened, ever - stored beside the oath, never shown as a setting. */
	private static final String KEY_OPENS = "beginHintOpens";
	/** Openings that get the short hint before the exact spot is spelled out. */
	private static final int SHORT_HINT_OPENS = 2;
	private static final String EXACT_HINT = "Ring the Cowbell Amulet 2 steps in front of the Wise Old Man";
	private static final int BOX_PAD = 8;
	private static final int BOX_GAP = 6;
	private static final int BOX_MAX_W = 220;
	/** The box stays fully visible this long, then fades out over BOX_FADE_MS and closes itself. */
	private static final long BOX_HOLD_MS = 3500L;
	private static final long BOX_FADE_MS = 1500L;

	private final Client client;
	private final Oath oath;
	private final OnboardingOverlay onboarding;
	private final MouseManager mouseManager;
	private final ConfigManager configManager;

	private boolean boxOpen;
	private long boxOpenedMs;
	private boolean hovered;
	/** The text for the box while it is open, fixed at the moment it was opened. */
	private String boxText = BattleMagePanel.BEGIN_HINT;
	/** Where the bubble and the box were last drawn, relative to the overlay's own corner. */
	private Rectangle bubbleHit;
	private Rectangle boxHit;

	private final MouseAdapter mouse = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent e)
		{
			if (e.getButton() != MouseEvent.BUTTON1 || e.isAltDown() || !showing())
			{
				return e;
			}
			Rectangle b = getBounds();
			if (b == null)
			{
				return e;
			}
			Point p = new Point(e.getX() - b.x, e.getY() - b.y);
			if (bubbleHit != null && bubbleHit.contains(p))
			{
				if (boxOpen)
				{
					boxOpen = false;
				}
				else
				{
					openBox();
				}
				e.consume();
			}
			else if (boxOpen && boxHit != null && boxHit.contains(p))
			{
				boxOpen = false;
				e.consume();
			}
			return e;
		}

		@Override
		public MouseEvent mouseMoved(MouseEvent e)
		{
			Rectangle b = getBounds();
			hovered = showing() && b != null && bubbleHit != null
				&& bubbleHit.contains(e.getX() - b.x, e.getY() - b.y);
			return e;
		}
	};

	@Inject
	BeginHintOverlay(Client client, Oath oath, OnboardingOverlay onboarding, MouseManager mouseManager,
		ConfigManager configManager)
	{
		this.client = client;
		this.oath = oath;
		this.onboarding = onboarding;
		this.mouseManager = mouseManager;
		this.configManager = configManager;
		setPosition(OverlayPosition.BOTTOM_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	void start()
	{
		boxOpen = false;
		mouseManager.registerMouseListener(mouse);
	}

	void stop()
	{
		mouseManager.unregisterMouseListener(mouse);
		boxOpen = false;
	}

	/** Counts this opening and picks the text: short for the first two, the exact spot after that. */
	private void openBox()
	{
		Integer seen = configManager.getConfiguration(Oath.GROUP, KEY_OPENS, Integer.class);
		int opens = (seen == null ? 0 : seen) + 1;
		configManager.setConfiguration(Oath.GROUP, KEY_OPENS, opens);
		boxText = opens > SHORT_HINT_OPENS ? EXACT_HINT : BattleMagePanel.BEGIN_HINT;
		boxOpen = true;
		boxOpenedMs = System.currentTimeMillis();
	}

	private boolean showing()
	{
		return !oath.isSworn() && !oath.inCeremony() && !onboarding.isActive() && client.getGameState() == GameState.LOGGED_IN;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!showing())
		{
			boxOpen = false;
			bubbleHit = null;
			boxHit = null;
			return null;
		}
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

		// After a few seconds the box fades away on its own.
		float boxAlpha = 1f;
		if (boxOpen)
		{
			long age = System.currentTimeMillis() - boxOpenedMs;
			if (age >= BOX_HOLD_MS + BOX_FADE_MS)
			{
				boxOpen = false;
			}
			else if (age > BOX_HOLD_MS)
			{
				boxAlpha = 1f - (age - BOX_HOLD_MS) / (float) BOX_FADE_MS;
			}
		}

		// Lay the box out first: it sits above the ring, so it decides the overlay's height.
		List<String> lines = new ArrayList<>();
		int boxW = 0;
		int boxH = 0;
		Font font = FontManager.getRunescapeFont();
		if (boxOpen)
		{
			g.setFont(font);
			FontMetrics fm = g.getFontMetrics();
			lines = wrap(boxText, fm, BOX_MAX_W - BOX_PAD * 2);
			for (String l : lines)
			{
				boxW = Math.max(boxW, fm.stringWidth(l));
			}
			boxW += BOX_PAD * 2;
			boxH = lines.size() * fm.getHeight() + BOX_PAD * 2;
		}

		int width = Math.max(BUBBLE_D + 2, boxW);
		int height = BUBBLE_H + (boxOpen ? boxH + BOX_GAP : 0);

		if (boxOpen)
		{
			boxHit = new Rectangle(0, 0, boxW, boxH);
			Composite before = g.getComposite();
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, Math.max(0f, boxAlpha)));
			g.setColor(BOX);
			g.fill(new RoundRectangle2D.Double(0, 0, boxW, boxH, 8, 8));
			g.setColor(AMBER);
			g.setStroke(new BasicStroke(1.5f));
			g.draw(new RoundRectangle2D.Double(0.75, 0.75, boxW - 1.5, boxH - 1.5, 8, 8));
			g.setFont(font);
			FontMetrics fm = g.getFontMetrics();
			int y = BOX_PAD + fm.getAscent();
			for (String l : lines)
			{
				// a shadow, as the game draws its own text
				g.setColor(Color.BLACK);
				g.drawString(l, BOX_PAD + 1, y + 1);
				g.setColor(BOX_TEXT);
				g.drawString(l, BOX_PAD, y);
				y += fm.getHeight();
			}
			g.setComposite(before);
		}
		else
		{
			boxHit = null;
		}

		drawRing(g, 1, height - BUBBLE_H);
		bubbleHit = new Rectangle(0, height - BUBBLE_H, BUBBLE_D + 2, BUBBLE_H);
		return new Dimension(width, height);
	}

	/**
	 * The amber ring and its "!", drawn flat: an open ring, a bar that tapers from a rounded top to a
	 * narrow foot, and a round dot. Proportions follow the reference icon, as fractions of the
	 * ring's outer radius.
	 */
	private void drawRing(Graphics2D g, int x, int y)
	{
		double cx = x + BUBBLE_D / 2.0;
		double cy = y + BUBBLE_D / 2.0;
		double r = RING_D / 2.0;
		float stroke = (float) Math.max(2.2, r * 0.15);

		Ellipse2D ring = new Ellipse2D.Double(cx - r + stroke / 2, cy - r + stroke / 2, RING_D - stroke, RING_D - stroke);

		double topW = r * 0.27;
		double footW = r * 0.11;
		double top = cy - r * 0.60;
		double foot = cy + r * 0.28;
		Area mark = new Area(new Ellipse2D.Double(cx - topW / 2, top, topW, topW));
		Path2D taper = new Path2D.Double();
		taper.moveTo(cx - topW / 2, top + topW / 2);
		taper.lineTo(cx + topW / 2, top + topW / 2);
		taper.lineTo(cx + footW / 2, foot);
		taper.lineTo(cx - footW / 2, foot);
		taper.closePath();
		mark.add(new Area(taper));
		mark.add(new Area(new Ellipse2D.Double(cx - footW / 2, foot - footW / 2, footW, footW)));
		double dotR = r * 0.14;
		mark.add(new Area(new Ellipse2D.Double(cx - dotR, cy + r * 0.47 - dotR, dotR * 2, dotR * 2)));

		Stroke old = g.getStroke();
		g.setStroke(new BasicStroke(stroke));

		// shadow, one pixel down and right
		g.translate(1, 1);
		g.setColor(SHADOW);
		g.draw(ring);
		g.fill(mark);
		g.translate(-1, -1);

		g.setColor(hovered ? AMBER_HOVER : AMBER);
		g.draw(ring);
		g.fill(mark);

		g.setStroke(old);
	}

	private static List<String> wrap(String text, FontMetrics fm, int maxW)
	{
		List<String> out = new ArrayList<>();
		StringBuilder line = new StringBuilder();
		for (String word : text.split(" "))
		{
			String next = line.length() == 0 ? word : line + " " + word;
			if (fm.stringWidth(next) > maxW && line.length() > 0)
			{
				out.add(line.toString());
				line = new StringBuilder(word);
			}
			else
			{
				line = new StringBuilder(next);
			}
		}
		if (line.length() > 0)
		{
			out.add(line.toString());
		}
		return out;
	}
}

package com.battlemage;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;

/**
 * The renderer for the oath screen's prose: line prefixes, word wrap and measuring. Everything about
 * the rules themselves lives in the rulebook ("Rules &amp; equipment" in the side panel).
 *
 * <h2>Line prefixes</h2>
 *
 * <table>
 *   <tr><td>{@code #}</td><td>a heading, drawn in the accent colour and upper-cased</td></tr>
 *   <tr><td>{@code -}</td><td>a bullet, indented with a dot in the accent colour</td></tr>
 *   <tr><td>{@code !}</td><td>a warning, drawn in amber</td></tr>
 *   <tr><td>{@code ""}</td><td>a blank line</td></tr>
 * </table>
 *
 * <p>{@link #height} measures by exactly the rules {@link #draw} draws by, so a panel is never sized
 * against different arithmetic than its contents.
 */
final class Briefing
{
	static final int LINE = 13;

	private static final Font BODY_FONT = new Font(Font.SANS_SERIF, Font.PLAIN, 11);
	private static final Font LABEL_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 9);
	private static final Color INK_MUTED = new Color(146, 156, 170);
	private static final Color WARN = new Color(214, 162, 78);

	private Briefing()
	{
	}

	/** Height of a copy block at the given width. */
	static int height(Graphics2D g, String[] lines, int width)
	{
		int h = 0;
		for (String raw : lines)
		{
			if (raw.isEmpty())
			{
				h += 7;
			}
			else if (raw.startsWith("#"))
			{
				h += 17;
			}
			else
			{
				boolean bullet = raw.startsWith("-");
				String text = raw.startsWith("!") || bullet ? raw.substring(1).trim() : raw;
				FontMetrics fm = g.getFontMetrics(BODY_FONT);
				h += LINE * Math.max(1, wrap(fm, text, bullet ? width - 12 : width).size());
			}
		}
		return h;
	}

	/** Draws a copy block and returns the y below it. */
	static int draw(Graphics2D g, int x, int y, int width, String[] lines, Color accent)
	{
		for (String raw : lines)
		{
			if (raw.isEmpty())
			{
				y += 7;
				continue;
			}
			if (raw.startsWith("#"))
			{
				g.setFont(LABEL_FONT);
				g.setColor(accent);
				g.drawString(raw.substring(1).toUpperCase(), x, y + 11);
				y += 17;
				continue;
			}
			boolean bullet = raw.startsWith("-");
			boolean warn = raw.startsWith("!");
			String text = bullet || warn ? raw.substring(1).trim() : raw;

			g.setFont(BODY_FONT);
			FontMetrics fm = g.getFontMetrics();
			int tx = bullet ? x + 12 : x;
			int tw = bullet ? width - 12 : width;
			boolean first = true;
			for (String line : wrap(fm, text, tw))
			{
				if (bullet && first)
				{
					g.setColor(accent);
					g.fillOval(x + 2, y + 5, 3, 3);
				}
				g.setColor(warn ? WARN : INK_MUTED);
				g.drawString(line, tx, y + 11);
				y += LINE;
				first = false;
			}
		}
		return y;
	}

	/**
	 * Greedy word wrap. Shared so that a block measured by {@link #height} and drawn by
	 * {@link #draw} always breaks in the same places.
	 */
	static List<String> wrap(FontMetrics fm, String text, int maxWidth)
	{
		List<String> lines = new ArrayList<>();
		if (text == null || text.isEmpty())
		{
			return lines;
		}
		StringBuilder line = new StringBuilder();
		for (String word : text.split("\\s+"))
		{
			String candidate = line.length() == 0 ? word : line + " " + word;
			if (fm.stringWidth(candidate) > maxWidth && line.length() > 0)
			{
				lines.add(line.toString());
				line = new StringBuilder(word);
			}
			else
			{
				line = new StringBuilder(candidate);
			}
		}
		if (line.length() > 0)
		{
			lines.add(line.toString());
		}
		return lines;
	}
}

package com.battlemage;

import java.awt.Color;
import java.awt.Composite;
import java.awt.AlphaComposite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.GradientPaint;
import java.awt.Paint;
import java.awt.RenderingHints;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * "Cast cards" menu mode: instead of a persistent battle menu, each cast drops a single card in from the
 * top-centre of the screen showing the family name + symbol (with the spell's icon faded behind it), then
 * dissolves. Newer cards appear at the top and push older ones down.
 */
class CastCardOverlay extends Overlay
{
	private static final long LIFE_MS = 2500L;
	private static final int CARD_H = 30;
	private static final int GAP = 6;

	private final Client client;
	private final BattleMagePlugin plugin;
	private final Appearance look;
	private final SpriteManager spriteManager;

	@Inject
	CastCardOverlay(Client client, BattleMagePlugin plugin, Appearance look, SpriteManager spriteManager)
	{
		this.client = client;
		this.plugin = plugin;
		this.look = look;
		this.spriteManager = spriteManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!look.castCardsEnabled())
		{
			return null;
		}
		List<BattleMagePlugin.CastCard> cards = plugin.castCards();
		if (cards.isEmpty())
		{
			return null;
		}

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

		final int screenW = client.getCanvasWidth() > 0 ? client.getCanvasWidth() : 520;
		final int margin = 8;
		final int gap = 6;
		final long now = System.currentTimeMillis();
		final int n = cards.size();
		final Composite base = g.getComposite();

		int flowX = margin;     // cursor: left-to-right, wrapping back to the left
		int flowY = margin;

		for (int i = 0; i < n; i++)
		{
			BattleMagePlugin.CastCard c = cards.get(i);
			double age = (now - c.spawnMs) / (double) LIFE_MS;
			if (age < 0 || age >= 1.0)
			{
				continue;
			}
			double in = Math.min(1.0, age / 0.12);        // quick slide-in
			float alpha = (float) Math.max(0f, Math.min(1f, in * (1.0 - age) * 1.3));
			int slideY = (int) Math.round((1.0 - in) * -24); // enters from above its landing spot

			g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 15));
			FontMetrics fm = g.getFontMetrics();

			int cardW = Math.max(120, fm.stringWidth(c.label) + 54);
			if (flowX + cardW > screenW - margin)
			{
				flowX = margin;                            // wrap back to the left
				flowY += CARD_H + GAP;
			}
			int x = flowX;
			int y = flowY + slideY;
			flowX += cardW + gap;

			Color col = plugin.colorFor(c.family);
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));

			// card body + border
			RoundRectangle2D box = new RoundRectangle2D.Float(x, y, cardW, CARD_H, 12, 12);
			g.setColor(new Color(0, 0, 0, 220));
			g.fill(box);

			// spell icon faded behind, shrunk within the card for weaker spells (c.scale)
			BufferedImage icon = c.spriteId > 0 ? spriteManager.getSprite(c.spriteId, 0) : null;
			if (icon != null)
			{
				float iconScale = c.scale <= 0 ? 1f : c.scale;
				Composite cc = g.getComposite();
				g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha * 0.45f));
				int ih = Math.round((CARD_H - 6) * iconScale);
				int iw = icon.getWidth() * ih / Math.max(1, icon.getHeight());
				int ix = x + cardW - iw - 8;                 // right-aligned with constant padding
				int iy = y + (CARD_H - ih) / 2;              // vertically centred in the full-size card
				g.drawImage(icon, ix, iy, iw, ih, null);
				g.setComposite(cc);
			}

			// poison fog: a green ombre wash over the card while poisoned
			if (plugin.isPoisoned())
			{
				Paint oldPaint = g.getPaint();
				g.setPaint(new GradientPaint(
					x, y, new Color(80, 205, 90, 55),
					x, y + CARD_H, new Color(40, 150, 55, 150)));
				g.fill(box);
				g.setPaint(oldPaint);
			}

			g.setColor(new Color(col.getRed(), col.getGreen(), col.getBlue(), 235));
			g.setStroke(new java.awt.BasicStroke(2f));
			g.draw(box);

			// label
			int tx = x + 12;
			int ty = y + CARD_H / 2 + fm.getAscent() / 2 - 2;
			g.setColor(new Color(0, 0, 0, 230));
			g.drawString(c.label, tx + 1, ty + 1);
			g.setColor(Color.WHITE);
			g.drawString(c.label, tx, ty);
		}

		g.setComposite(base);
		return null;
	}
}

package com.battlemage;

import java.awt.event.KeyEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.Player;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetModelType;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.game.chatbox.ChatboxInput;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.input.KeyListener;

/**
 * Game-style conversations in the chatbox: an NPC or the player speaking beside their chat head,
 * "Click here to continue", and "Select an Option" menus - drawn with RuneLite's chatbox panel, so
 * nothing is sent to the game.
 *
 * <p>A conversation is a list of {@link Line}s played in order, followed by whatever runs next
 * (usually a {@link #menu}). Space or a click moves on; Escape closes the chatbox, which simply
 * ends the conversation - nothing waits on it.
 */
@Singleton
class ChatDialogue
{
	/** Chat-head expressions. Each has four variants, one per line count; {@link #anim} picks it. */
	enum Mood
	{
		NEUTRAL(588),
		HAPPY(567),
		LAUGH(605),
		CONFUSED(575),
		QUESTION(554),
		SHOCKED(571),
		ANGRY(614);

		final int base;

		Mood(int base)
		{
			this.base = base;
		}

		/** The variant whose mouth movement lasts as long as the text: one to four lines. */
		int anim(String text)
		{
			int lines = Math.max(1, Math.min(4, (text.length() + CHARS_PER_LINE - 1) / CHARS_PER_LINE));
			return base + lines - 1;
		}
	}

	/** One line of a conversation. */
	static final class Line
	{
		final boolean player;
		final Mood mood;
		final String text;

		private Line(boolean player, Mood mood, String text)
		{
			this.player = player;
			this.mood = mood;
			this.text = text;
		}

		static Line npc(Mood mood, String text)
		{
			return new Line(false, mood, text);
		}

		static Line player(Mood mood, String text)
		{
			return new Line(true, mood, text);
		}
	}

	/** One choice in a "Select an Option" menu. */
	static final class Option
	{
		final String text;
		final Runnable action;

		Option(String text, Runnable action)
		{
			this.text = text;
			this.action = action;
		}
	}

	// The chatbox's own palette and font for dialogue.
	private static final int NAME_COLOR = 0x800000;
	private static final int TEXT_COLOR = 0x000000;
	private static final int CONTINUE_COLOR = 0x0000FF;
	private static final int HOVER_COLOR = 0xFFFFFF;
	private static final int FONT = FontID.QUILL_8;

	/** Rough characters per wrapped line of dialogue, used only to pick the chat-head animation. */
	private static final int CHARS_PER_LINE = 52;

	// Chat-head placement: the speaker's head sits at the side, the words in the space beside it.
	// The NPC is on the left and the player on the right, as in the game.
	/** Distance of each head from its own edge of the chatbox. The NPC's sits 10px further left. */
	private static final int HEAD_X_PLAYER = 46;
	private static final int HEAD_X_NPC = HEAD_X_PLAYER - 10;
	private static final int HEAD_SIZE = 32;
	private static final int HEAD_ZOOM = 796;
	private static final int HEAD_ROT_X = 40;
	private static final int HEAD_ROT_Z_NPC = 1882;
	private static final int HEAD_ROT_Z_PLAYER = 166;
	/** Where the text column starts, measured from the head's side of the chatbox. */
	private static final int TEXT_INSET = 96;
	/** Breathing room on the far side of the text column. */
	private static final int TEXT_MARGIN = 20;

	private final Client client;
	private final ChatboxPanelManager panels;

	@Inject
	ChatDialogue(Client client, ChatboxPanelManager panels)
	{
		this.client = client;
		this.panels = panels;
	}

	/**
	 * Plays these lines in order, then runs {@code after}. With no {@code after} the chatbox closes
	 * once the last line is continued past.
	 *
	 * @param npcId   whose chat head the NPC lines show
	 * @param npcName the name above the NPC lines
	 */
	void play(int npcId, String npcName, List<Line> lines, Runnable after)
	{
		playFrom(npcId, npcName, new ArrayList<>(lines), 0, after);
	}

	void play(int npcId, String npcName, Line line, Runnable after)
	{
		play(npcId, npcName, Collections.singletonList(line), after);
	}

	/** A "Select an Option" menu. Picking an option runs its action; Escape just closes the chatbox. */
	void menu(String title, List<Option> options)
	{
		panels.openInput(new MenuPanel(title, new ArrayList<>(options)));
	}

	/** Ends the conversation that is open. */
	void close()
	{
		panels.close();
	}

	/** Ends the conversation only if one of ours is showing, leaving the game's own dialogues alone. */
	void closeIfOpen()
	{
		ChatboxInput current = panels.getCurrentInput();
		if (current instanceof LinePanel || current instanceof MenuPanel)
		{
			panels.close();
		}
	}

	private void playFrom(int npcId, String npcName, List<Line> lines, int i, Runnable after)
	{
		if (i >= lines.size())
		{
			if (after != null)
			{
				after.run();
			}
			else
			{
				panels.close();
			}
			return;
		}
		Line line = lines.get(i);
		String name = line.player ? playerName() : npcName;
		panels.openInput(new LinePanel(line, npcId, name, () -> playFrom(npcId, npcName, lines, i + 1, after)));
	}

	private String playerName()
	{
		Player p = client.getLocalPlayer();
		String n = p == null ? null : p.getName();
		return n == null ? "" : n.replace(' ', ' ');
	}

	// ------------------------------------------------------------------ one spoken line

	private final class LinePanel extends ChatboxInput implements KeyListener
	{
		private final Line line;
		private final int npcId;
		private final String name;
		private final Runnable next;
		/** A line only moves on once, however many clicks and key presses arrive. */
		private boolean done;

		LinePanel(Line line, int npcId, String name, Runnable next)
		{
			this.line = line;
			this.npcId = npcId;
			this.name = name;
			this.next = next;
		}

		@Override
		protected void open()
		{
			Widget c = panels.getContainerWidget();
			int side = line.player ? WidgetPositionMode.ABSOLUTE_RIGHT : WidgetPositionMode.ABSOLUTE_LEFT;

			Widget head = c.createChild(-1, WidgetType.MODEL);
			if (line.player)
			{
				head.setModelType(WidgetModelType.LOCAL_PLAYER_CHATHEAD);
				head.setModelId(0);
			}
			else
			{
				head.setModelType(WidgetModelType.NPC_CHATHEAD);
				head.setModelId(npcId);
			}
			head.setAnimationId(line.mood.anim(line.text));
			head.setModelZoom(HEAD_ZOOM);
			head.setRotationX(HEAD_ROT_X);
			head.setRotationZ(line.player ? HEAD_ROT_Z_PLAYER : HEAD_ROT_Z_NPC);
			head.setXPositionMode(side);
			head.setOriginalX(line.player ? HEAD_X_PLAYER : HEAD_X_NPC);
			head.setYPositionMode(WidgetPositionMode.ABSOLUTE_CENTER);
			head.setOriginalY(0);
			head.setOriginalWidth(HEAD_SIZE);
			head.setOriginalHeight(HEAD_SIZE);
			head.revalidate();

			Widget title = textIn(c, side, NAME_COLOR, name);
			title.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
			title.setOriginalY(8);
			title.setOriginalHeight(18);
			title.revalidate();

			Widget body = textIn(c, side, TEXT_COLOR, line.text);
			body.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
			body.setOriginalY(28);
			body.setHeightMode(WidgetSizeMode.MINUS);
			body.setOriginalHeight(28 + 30);
			body.setYTextAlignment(WidgetTextAlignment.CENTER);
			body.revalidate();

			Widget cont = textIn(c, side, CONTINUE_COLOR, "Click here to continue");
			cont.setYPositionMode(WidgetPositionMode.ABSOLUTE_BOTTOM);
			cont.setOriginalY(8);
			cont.setOriginalHeight(18);
			cont.setAction(0, "Continue");
			cont.setOnOpListener((JavaScriptCallback) ev -> advance());
			cont.setOnMouseOverListener((JavaScriptCallback) ev -> cont.setTextColor(HOVER_COLOR));
			cont.setOnMouseLeaveListener((JavaScriptCallback) ev -> cont.setTextColor(CONTINUE_COLOR));
			cont.setHasListener(true);
			cont.revalidate();
		}

		private void advance()
		{
			if (done)
			{
				return;
			}
			done = true;
			next.run();
		}

		@Override
		public void keyTyped(KeyEvent e)
		{
			if (!panels.shouldTakeInput())
			{
				return;
			}
			char ch = e.getKeyChar();
			if (ch == ' ')
			{
				e.consume();
				advance();
			}
			else if (ch == '\033')
			{
				e.consume();
				panels.close();
			}
		}

		@Override
		public void keyPressed(KeyEvent e)
		{
			if (panels.shouldTakeInput()
				&& (e.getKeyCode() == KeyEvent.VK_SPACE || e.getKeyCode() == KeyEvent.VK_ESCAPE))
			{
				e.consume();
			}
		}

		@Override
		public void keyReleased(KeyEvent e)
		{
		}
	}

	/** A centred line of dialogue text in the column beside the head. */
	private static Widget textIn(Widget c, int side, int color, String text)
	{
		Widget w = c.createChild(-1, WidgetType.TEXT);
		w.setText(text);
		w.setTextColor(color);
		w.setFontId(FONT);
		w.setXPositionMode(side);
		w.setOriginalX(TEXT_INSET);
		w.setWidthMode(WidgetSizeMode.MINUS);
		w.setOriginalWidth(TEXT_INSET + TEXT_MARGIN);
		w.setXTextAlignment(WidgetTextAlignment.CENTER);
		w.setYTextAlignment(WidgetTextAlignment.CENTER);
		return w;
	}

	// ------------------------------------------------------------------ "Select an Option"

	private final class MenuPanel extends ChatboxInput implements KeyListener
	{
		private final String title;
		private final List<Option> options;
		private boolean done;

		MenuPanel(String title, List<Option> options)
		{
			this.title = title;
			this.options = options;
		}

		@Override
		protected void open()
		{
			Widget c = panels.getContainerWidget();

			Widget head = c.createChild(-1, WidgetType.TEXT);
			head.setText(title);
			head.setTextColor(NAME_COLOR);
			head.setFontId(FONT);
			head.setXPositionMode(WidgetPositionMode.ABSOLUTE_CENTER);
			head.setOriginalX(0);
			head.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
			head.setOriginalY(8);
			head.setOriginalHeight(20);
			head.setWidthMode(WidgetSizeMode.MINUS);
			head.setOriginalWidth(0);
			head.setXTextAlignment(WidgetTextAlignment.CENTER);
			head.setYTextAlignment(WidgetTextAlignment.CENTER);
			head.revalidate();

			// Spread the options evenly down the rest of the box, no further apart than the game does.
			int top = 8 + 20 + 4;
			int room = c.getHeight() - top - 8;
			int step = Math.min(options.size() >= 3 ? 20 : 26, room / Math.max(1, options.size()));
			int y = top + Math.max(0, (room - step * options.size()) / 2);

			for (Option o : options)
			{
				Widget w = c.createChild(-1, WidgetType.TEXT);
				w.setText(o.text);
				w.setTextColor(TEXT_COLOR);
				w.setFontId(FONT);
				w.setXPositionMode(WidgetPositionMode.ABSOLUTE_CENTER);
				w.setOriginalX(0);
				w.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
				w.setOriginalY(y);
				w.setOriginalHeight(step);
				w.setWidthMode(WidgetSizeMode.MINUS);
				w.setOriginalWidth(0);
				w.setXTextAlignment(WidgetTextAlignment.CENTER);
				w.setYTextAlignment(WidgetTextAlignment.CENTER);
				w.setAction(0, "Continue");
				w.setOnOpListener((JavaScriptCallback) ev -> pick(o));
				w.setOnMouseOverListener((JavaScriptCallback) ev -> w.setTextColor(HOVER_COLOR));
				w.setOnMouseLeaveListener((JavaScriptCallback) ev -> w.setTextColor(TEXT_COLOR));
				w.setHasListener(true);
				w.revalidate();
				y += step;
			}
		}

		private void pick(Option o)
		{
			if (done)
			{
				return;
			}
			done = true;
			o.action.run();
		}

		@Override
		public void keyTyped(KeyEvent e)
		{
			if (!panels.shouldTakeInput())
			{
				return;
			}
			char ch = e.getKeyChar();
			if (ch == '\033')
			{
				e.consume();
				panels.close();
				return;
			}
			int n = ch - '1';
			if (n >= 0 && n < options.size())
			{
				e.consume();
				pick(options.get(n));
			}
		}

		@Override
		public void keyPressed(KeyEvent e)
		{
			if (panels.shouldTakeInput() && e.getKeyCode() == KeyEvent.VK_ESCAPE)
			{
				e.consume();
			}
		}

		@Override
		public void keyReleased(KeyEvent e)
		{
		}
	}
}

package com.battlemage;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Marks the combat-tab buttons that are locked out - the autocast box (autocasting is disabled) - by
 * covering the whole box with a translucent red block and a slash. Overlapping matches within one box
 * are merged so each box gets exactly one block.
 */
class CombatLockOverlay extends Overlay
{
	private final Client client;

	@Inject
	CombatLockOverlay(Client client)
	{
		this.client = client;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		List<Rectangle> matches = new ArrayList<>();
		Widget[] roots = client.getWidgetRoots();
		if (roots != null)
		{
			for (Widget root : roots)
			{
				collect(root, matches, 0);
			}
		}
		for (Rectangle r : merge(matches))
		{
			drawBlock(g, r);
		}
		return null;
	}

	private void collect(Widget w, List<Rectangle> out, int depth)
	{
		if (w == null || depth > 8)
		{
			return;
		}
		if (!w.isHidden() && isLocked(w))
		{
			Rectangle b = w.getBounds();
			if (b != null && b.width > 4 && b.height > 4)
			{
				out.add(b);
			}
		}
		collectAll(w.getStaticChildren(), out, depth);
		collectAll(w.getDynamicChildren(), out, depth);
		collectAll(w.getNestedChildren(), out, depth);
	}

	private void collectAll(Widget[] children, List<Rectangle> out, int depth)
	{
		if (children == null)
		{
			return;
		}
		for (Widget c : children)
		{
			collect(c, out, depth + 1);
		}
	}

	/** Merge overlapping rectangles into their union, so each box ends up with one block. */
	private List<Rectangle> merge(List<Rectangle> rects)
	{
		List<Rectangle> merged = new ArrayList<>();
		for (Rectangle r : rects)
		{
			boolean joined = false;
			for (int i = 0; i < merged.size(); i++)
			{
				if (merged.get(i).intersects(r))
				{
					merged.set(i, merged.get(i).union(r));
					joined = true;
					break;
				}
			}
			if (!joined)
			{
				merged.add(new Rectangle(r));
			}
		}
		// a second pass catches rectangles that only overlap after a union grew
		boolean changed = true;
		while (changed)
		{
			changed = false;
			outer:
			for (int i = 0; i < merged.size(); i++)
			{
				for (int j = i + 1; j < merged.size(); j++)
				{
					if (merged.get(i).intersects(merged.get(j)))
					{
						merged.set(i, merged.get(i).union(merged.get(j)));
						merged.remove(j);
						changed = true;
						break outer;
					}
				}
			}
		}
		return merged;
	}

	private boolean isLocked(Widget w)
	{
		StringBuilder sb = new StringBuilder();
		if (w.getName() != null)
		{
			sb.append(w.getName().toLowerCase(Locale.ROOT)).append(' ');
		}
		if (w.getText() != null)
		{
			sb.append(w.getText().toLowerCase(Locale.ROOT)).append(' ');
		}
		String[] actions = w.getActions();
		if (actions != null)
		{
			for (String a : actions)
			{
				if (a != null)
				{
					sb.append(a.toLowerCase(Locale.ROOT)).append(' ');
				}
			}
		}
		String s = sb.toString();
		return s.contains("auto-cast") || s.contains("autocast") || s.contains("choose spell");
	}

	private void drawBlock(Graphics2D g, Rectangle r)
	{
		// translucent red wash over the whole box
		g.setColor(new Color(200, 0, 0, 80));
		g.fillRect(r.x, r.y, r.width, r.height);

		// dark backing for contrast
		g.setStroke(new BasicStroke(4f));
		g.setColor(new Color(0, 0, 0, 150));
		g.drawLine(r.x, r.y, r.x + r.width, r.y + r.height);
		g.drawLine(r.x + r.width, r.y, r.x, r.y + r.height);

		// red border + diagonal slash
		g.setStroke(new BasicStroke(2.5f));
		g.setColor(new Color(230, 20, 20, 245));
		g.drawRect(r.x, r.y, r.width, r.height);
		g.drawLine(r.x, r.y, r.x + r.width, r.y + r.height);
		g.drawLine(r.x + r.width, r.y, r.x, r.y + r.height);
	}
}

package com.battlemage;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Deserialised shape of {@code /battlemage-codex.json} - the bundled content pack that holds every
 * back-end rule the plugin enforces.
 *
 * <p>Nothing here is user-editable at runtime. The pack ships inside the jar, is authored from the
 * Battle-Mage Codex form, and is the single source of truth for equipment lists, animation IDs,
 * PKP costs and gains, spec weapons, spec effects, item effects and every allowed-equipment
 * exception. Only visual customisation remains in {@link BattleMageConfig}.
 *
 * <p>Field names match the JSON keys exactly, which in turn match the old config key names, so a
 * value can be traced from the codex form through to the call site that reads it.
 */
public class ContentPack
{
	public int formatVersion;

	public Shared shared = new Shared();

	/**
	 * Keyed by faction alone, e.g. {@code SARADOMIN}.
	 */
	public Map<String, Profile> profiles = new LinkedHashMap<>();

	public Profile profile(String key)
	{
		return profiles.get(key);
	}

	// ------------------------------------------------------------------ shared

	/** Rules that are identical for every faction. */
	public static class Shared
	{
		/**
		 * Consumable effects that apply under every god, in the same shape as a profile's
		 * {@link Consumables#consumableEffects}. A god that lists the same item in its own profile
		 * replaces this entry for that god, which is how a drink acts one way for most gods and
		 * another way for one.
		 */
		public List<Effect> consumableEffects = new ArrayList<>();

		/** Drinks that blunt PKP gain for a while - see {@link Alcohol}. */
		public Alcohol alcohol = new Alcohol();

		/**
		 * Equipment that makes every spell cost more while it is worn, as {@code name -> percent of
		 * the normal cost} (150 = one and a half times). Several worn at once multiply.
		 */
		public Map<String, Integer> spellCostItems = new LinkedHashMap<>();

		/**
		 * Spells with a cost of their own, as {@code name -> PKP}, beating the combat and curse costs
		 * whatever the Magic level (Crumble Undead, the binds).
		 */
		public Map<String, Integer> spellCosts = new LinkedHashMap<>();

		/**
		 * Spells that get cheaper with Magic level: from {@link LevelCost#level} up, the spell costs
		 * {@link LevelCost#cost} instead of its normal cost. Below the level it costs as usual.
		 */
		public Map<String, LevelCost> spellLevelCosts = new LinkedHashMap<>();

		/**
		 * Equipment that adds a PKP buffer while worn, as {@code name -> buffer}. A buffer is extra
		 * room before a state trips: the {@link Buffer#depletion} side counts as PKP you still have
		 * when a cast would deplete you, and the {@link Buffer#overload} side as PKP you are still
		 * missing when a gain would overload you. Worn buffers add up.
		 */
		public Map<String, Buffer> pkpBufferItems = new LinkedHashMap<>();

		/**
		 * Equipment that may save you from Overload or Depletion while worn - see {@link StateSave}.
		 * Rolled each time a cast or a gain would newly trip either state; on a save the bar stops at
		 * empty or full instead. Several worn take the best chance, not the sum.
		 */
		public Map<String, StateSave> stateSaveItems = new LinkedHashMap<>();

		/**
		 * Named groups of spells, as {@code group -> spell names}, so a rule can say "ancient" instead
		 * of listing sixteen spells.
		 */
		public Map<String, List<String>> spellGroups = new LinkedHashMap<>();

		/**
		 * Equipment that changes what spells cost while worn, as {@code item -> (target -> cost)}. A
		 * target is a spell name, a {@link #spellGroups} name, or "curse" / "combat" for a whole
		 * family. Only ever lowers a cost: the cheapest that applies wins.
		 */
		public Map<String, Map<String, Integer>> wornSpellCosts = new LinkedHashMap<>();

		/**
		 * Worn items that take PKP off a spell's cost, as {@code item -> (target -> PKP off)}, targets as in
		 * {@link #wornSpellCosts} - the elemental staves.
		 */
		public Map<String, Map<String, Integer>> wornSpellDiscounts = new LinkedHashMap<>();

		/** Equipment sets with a bonus for wearing enough pieces - see {@link SetBonus}. */
		public Map<String, SetBonus> setBonuses = new LinkedHashMap<>();

		/**
		 * Equipment that cancels CRITICAL OVERLOAD as it starts, as {@code item -> cooldown in
		 * seconds}. Once used it rests for the cooldown before it can do it again.
		 */
		public Map<String, Integer> criticalSaveItems = new LinkedHashMap<>();

		/** Game messages that set off effects - see {@link ChatTrigger}. */
		public List<ChatTrigger> chatTriggers = new ArrayList<>();

		/** Equipment with flat or percent bonuses while worn - see {@link WornBonus}. */
		public Map<String, WornBonus> wornBonuses = new LinkedHashMap<>();

		/** Equipment with worn chances - see {@link ChanceEffect}. */
		public Map<String, ChanceEffect> chanceItems = new LinkedHashMap<>();

		/** Equipment that makes you immune to Depletion while you are in the Wilderness. */
		public List<String> wildernessDepletionImmuneItems = new ArrayList<>();

		/**
		 * Items that are not used up, as {@code item -> (menu option -> effect)} - the Dwarven rock
		 * cake's Eat and Guzzle, the Locator orb's Feel. Applied once per game tick per item.
		 */
		public Map<String, Map<String, OptionEffect>> itemOptionEffects = new LinkedHashMap<>();

		/** Ranged weapons whose PKP shrinks with each throw in a row - see {@link Decay}. */
		public Map<String, Decay> decayingRangedWeapons = new LinkedHashMap<>();

		/**
		 * Melee weapons whose every hit is a coin flip, as {@code weapon -> amount}: heads earns that
		 * much PKP, tails costs it (the Ham joint).
		 */
		public Map<String, Integer> weaponHitGambles = new LinkedHashMap<>();

		/**
		 * Equipment every god lets you wear, whatever else the pack says.
		 *
		 * <p>Quest gear: the flail a quest hands you, the staff a teleport needs, the amulet that
		 * lets you talk to a ghost. Shared rather than per-god because a quest does not care which
		 * god you swore to, and being unable to finish one because of a plugin rule is not a
		 * difficulty setting - it is a dead end.
		 *
		 * <p><b>This list wins.</b> It is checked before every other equipment rule: the
		 * magic-attack gate, the gear force-block, the per-god blocked weapons, blanket weapon
		 * blocking and the pacifist class. An item here is equippable, is never marked off-limits,
		 * and never triggers pacifism, whichever god is in force and whatever other list it also
		 * appears on.
		 *
		 * <p>Scope is deliberately equipment. It does not lift the CRITICAL OVERLOAD lockdown, which
		 * keeps its own one-item exemption on each profile, and it says nothing about food or
		 * potions.
		 *
		 * <p>An entry may name the quests it belongs to, in which case it is only a quest item while
		 * one of them is <b>in progress</b>. See {@link QuestItem}.
		 */
		public List<QuestItem> questItems = new ArrayList<>();

		/**
		 * Ranged weapons every god permits - the common floor.
		 *
		 * <p>Unioned with each profile's own {@code ranged.rangedWeapons}, so this is where a weapon
		 * that is legal for everyone is named once, and a profile's list is for that god's additions
		 * on top. Neither replaces the other.
		 *
		 * <p>An allow-list, not an override: it sits with the other permissions in the equipment
		 * chain, so {@link Weapons#blockedWeapons} still bars anything named on both. Being here also
		 * makes a weapon eligible for the ranged PKP restore, which is what makes ranged worth
		 * carrying at all - the per-weapon amounts stay per-god in {@code ranged.pkpRangedWeapons}.
		 */
		public List<String> rangedWeapons = new ArrayList<>();

		/**
		 * Equipment every god lets you wear, bypassing the default rules.
		 *
		 * <p>The shared twin of {@link Gear#magicGearExceptions}, and unioned with it: gear that is
		 * legal for everyone is named once here, and a profile's list carries that god's additions.
		 *
		 * <p>"Default rules" means the two that apply automatically to everything - the magic-attack
		 * gate and the blanket weapon block. It does <b>not</b> beat a god's explicitly authored
		 * denials, {@link Gear#magicGearForceBlock} and {@link Weapons#blockedWeapons}, which sit
		 * above every allow-list: a god that names a piece there has said something deliberate about
		 * it, and this list is a floor, not an override. {@link Shared#questItems} is the override.
		 */
		public List<String> gearExceptions = new ArrayList<>();

		/**
		 * Shields every god lets you wear - armour, kept in its own list so the plugin knows which
		 * pieces are shields. Legal exactly like {@link #gearExceptions}; unioned with each god's
		 * {@link Gear#shields}.
		 */
		public List<String> shields = new ArrayList<>();

		/**
		 * PKP gained per block while wearing this shield, as {@code name -> PKP}. Replaces the god's
		 * {@link Pool#blockRestore} for that block, under every god - including gods whose blockRestore
		 * is 0. A shield missing here blocks for the god's usual amount.
		 */
		public Map<String, Integer> shieldBlockPkp = new LinkedHashMap<>();

		/**
		 * Off-hand items that earn no PKP from blocking at all - god d'hide shields and defenders. Beats the god's
		 * {@link Pool#blockRestore} and any {@link #shieldBlockPkp} amount.
		 */
		public List<String> noBlockPkpItems = new ArrayList<>();

		/**
		 * Off-hand items that COST PKP when you block with them, as {@code name -> PKP lost} (the books
		 * and the Antler guard, 33 each by default). Applies under every god and beats every other
		 * block rule. Like a spell cost, it can take the bar below zero.
		 */
		public Map<String, Integer> blockPenaltyItems = new LinkedHashMap<>();

		/**
		 * Weapons every god lets you wield - the common floor.
		 *
		 * <p>The shared twin of {@link Weapons#weaponExceptions}, unioned with it exactly as
		 * {@link #gearExceptions} is with the gear list. A weapon legal for everyone is named once
		 * here; a profile's list carries that god's additions.
		 *
		 * <p>Deliberately separate from {@link #questItems}. Both make a weapon wieldable, but they
		 * are different statements: this one says "the gate does not apply to this weapon", and a
		 * god can still overrule it with {@link Weapons#blockedWeapons} or
		 * {@link Gear#magicGearForceBlock}. The quest list says "no ruleset may block this", and
		 * nothing overrules it. A weapon that is merely allowed belongs here; a weapon a quest
		 * requires belongs there.
		 */
		public List<String> weaponExceptions = new ArrayList<>();

		/**
		 * Items that bar every attack and every combat spell while carried - the common floor.
		 *
		 * <p>The shared twin of {@link Pacifist#pacifistItems}, unioned with it exactly as the three
		 * lists above are with theirs. The odd one of the four in that it is a <em>ban</em> rather
		 * than a permission: a skilling tool named here disarms you under every god, and a profile's
		 * list adds only the ones that god disarms on top.
		 *
		 * <p>Quest items still beat it, as they beat every other rule.
		 */
		public List<String> pacifistItems = new ArrayList<>();

		/**
		 * Weapons no god lets you wield - the common ban floor.
		 *
		 * <p>The powered staves live here: they pass the magic-attack gate with room to spare, so
		 * nothing else in the pack would ever stop them, and "cast with the spellbook, not with a
		 * staff that casts for you" is a rule of the mode rather than of any one god.
		 *
		 * <p><b>A god can lift it.</b> Naming a weapon in that god's own
		 * {@link Weapons#weaponExceptions} or {@link Ranged#rangedWeapons} removes it from this floor
		 * for that god only - which is how Zaros keeps the charged Thammaron's and Accursed sceptres
		 * while the other three stay barred from them, without copying the staff list into four
		 * profiles. A god's own {@link Weapons#blockedWeapons} cannot be lifted that way: a denial the
		 * god wrote itself outranks its own allow-list.
		 *
		 * <p>Quest items beat this, as they beat every other rule.
		 */
		public List<String> blockedWeapons = new ArrayList<>();

		/**
		 * Spec weapons, their PKP delta and the effects they fire - for every god.
		 *
		 * <p>Shared because a special attack is a property of the weapon, not of a doctrine: the
		 * Dragon battleaxe buys three attacks of overload immunity whoever is holding it. The four
		 * profiles carried identical copies of this table; what differs between gods is which of
		 * these weapons they let you <em>hold</em>, and that is the exception lists' job.
		 *
		 * <p><b>Being listed here does not make a weapon equippable.</b> The table says what happens
		 * when the spec fires, nothing more - a weapon still has to clear the magic-attack gate or
		 * sit on an allow-list like any other. Listing the Dragon claws' effect is not the same
		 * statement as letting Saradomin wield them.
		 */
		public List<Effect> specAttackWeapons = new ArrayList<>();

		/**
		 * Ranged weapons whose hit is worth something other than the base restore, as
		 * {@code name -> PKP}. Shared for the same reason the spec table is: how much a weapon
		 * returns per hit is a fact about the weapon, not about the god holding it.
		 *
		 * <p>Anything not named here uses {@link Ranged#rangedRestore}. A <b>negative</b> amount is
		 * allowed and means the weapon costs PKP to fire rather than paying for it.
		 *
		 * <p>Like the spec table, being named here is not a permission - the weapon still has to be
		 * on a ranged or weapon allow-list to be wielded at all.
		 */
		public Map<String, Integer> pkpRangedWeapons = new LinkedHashMap<>();

		/**
		 * Weapons whose freeze holds for as long as you keep using them, instead of for a fixed time.
		 *
		 * <p>A freeze armed by one of these weapons has no clock. It lasts while you keep attacking
		 * with that same weapon's melee or casting one of the spells named beside it, and ends the
		 * moment you cast anything else, attack with anything else, or drop out of combat for
		 * {@code regen.oocThresholdTicks}. The three god staves are what this exists for: the
		 * staff and its own god spell are a pair, and using one without the other breaks it.
		 *
		 * <p>Shared, like the spec table itself, because which spells a staff is paired with is a
		 * fact about the staff and not about anyone's doctrine. A weapon NOT named here keeps the
		 * ordinary timed freeze.
		 */
		public List<SustainedFreeze> sustainedFreeze = new ArrayList<>();

		public Gate gate = new Gate();
		public Anims anims = new Anims();
		public Varps varps = new Varps();
		public Lockdown lockdown = new Lockdown();
		public Cannon cannon = new Cannon();
	}

	/** A spell's cheaper cost from a Magic level up - see {@link Shared#spellLevelCosts}. */
	public static class LevelCost
	{
		public int level = 99;
		public int cost = 50;
	}

	/** A set bonus: wear at least {@link #minPieces} of {@link #pieces} and the costs change. */
	public static class SetBonus
	{
		/** Item names; two worn items with the same name (a robe top and bottom) count twice. */
		public List<String> pieces = new ArrayList<>();
		public int minPieces = 2;
		/** {@code target -> percent of the normal cost}, targets as in {@link Shared#wornSpellCosts}. */
		public Map<String, Integer> costPercent = new LinkedHashMap<>();
		/** {@code target -> PKP taken off the cost}, after the percent. "all" means every spell. */
		public Map<String, Integer> costMinus = new LinkedHashMap<>();
		/** A PKP buffer the set adds on top of its pieces' own, each side on its own. */
		public int bufferOverload;
		public int bufferDepletion;
		/** With enough pieces on, CRITICAL OVERLOAD cannot start at all. */
		public boolean noCritical;
		/** With enough pieces on, a percent chance to stop a fresh overload. */
		public int saveOverload;
		/** Tooltips say "full set" instead of a piece count. */
		public boolean fullSet;
		/** The name tooltips show, when it differs from the key (two bonuses for one set). */
		public String name;
	}

	/** A game message that sets off effect codes when it appears (matched as lower-case text). */
	public static class ChatTrigger
	{
		public String contains = "";
		/** Effect codes, joined with "+", as in a consumable's effects (e.g. "CO+CD"). */
		public String effects = "";
	}

	/** A ranged weapon whose PKP shrinks with each throw in a row. */
	public static class Decay
	{
		/** PKP for the first throw. */
		public int first = 50;
		/** Each further throw earns this fraction of the one before. */
		public double factor = 0.5;
		/** A gap longer than this, in seconds, starts the chain over. */
		public int resetSeconds = 3;
		/** Its throws fill the bar to the top at most and never overload. */
		public boolean neverOverload = true;
	}

	/** One save item: its chance in percent, and the effect played on the player when it saves. */
	public static class StateSave
	{
		public int chance;
		/** A spot-anim id (a graphic from the game cache), or 0 for none. */
		public int spotanim;
		/** Which states it can save you from. Overload and depletion by default; CRITICAL OVERLOAD only when set. */
		public boolean overload = true;
		public boolean depletion = true;
		public boolean critical;
	}

	/** What an item adds while worn. Several worn add up; percents multiply. */
	public static class WornBonus
	{
		/** Extra PKP each melee hit earns. */
		public int meleeGain;
		/** Extra PKP each block earns (only on a block that already moves PKP). */
		public int blockGain;
		/** Out-of-combat regen speed, in percent of normal (150 = half as fast again). */
		public int regenPercent = 100;
		/** Food and drink PKP gains, in percent of normal. */
		public int restorePercent = 100;
	}

	/** Worn chances that change an action, each in percent. */
	public static class ChanceEffect
	{
		/** Chance a cast costs nothing. */
		public int freeCast;
		/** Chance a melee or ranged gain does not land. */
		public int noGain;
	}

	/** A non-consumed item's menu option and what it does each time it is used. */
	public static class OptionEffect
	{
		public int delta;
		/** Effect codes joined with "+", as in a consumable's effects. */
		public String effects = "";
	}

	/** One worn item's PKP buffer, each side on its own - see {@link Shared#pkpBufferItems}. */
	public static class Buffer
	{
		public int overload;
		public int depletion;
	}

	/**
	 * The Dwarf multicannon window: it may be set up only while Ranged is still low.
	 *
	 * <p>Shared, because it is a rule about the run rather than about any god's doctrine, and a
	 * window rather than a requirement - the usual shape is "you need level X", this one is "you may
	 * only while you are under level X", which is why it reads as a maximum.
	 */
	public static class Cannon
	{
		public boolean enforceCannonLevel = true;

		/**
		 * The first Ranged level at which the cannon is no longer yours to place. Strictly a ceiling:
		 * 45 means 44 may set one up and 45 may not.
		 */
		public int maxRangedLevel = 45;

		/**
		 * The menu options that place a cannon. Matched case-insensitively against the whole option.
		 * Only these are removed - Fire, Pick-up, Repair and the rest are untouched, so a cannon
		 * already on the ground keeps working after the window closes.
		 */
		public List<String> setupActions = new ArrayList<>();

		/**
		 * Matched as a substring of the item's name, lower-cased. A keyword rather than a list of
		 * ids because the pieces, the packed set and every ornamental re-skin all carry "cannon" in
		 * the name, and an id list that missed one would be a rule that silently never fired.
		 */
		public String cannonItemKeyword = "cannon";
	}

	/**
	 * The magic-attack gate. Deliberately shared: the weapon minimum and armour threshold are the
	 * same whichever god a player picks. Faction difficulty comes from the exception
	 * lists, costs and punishments on each profile instead.
	 */
	public static class Gate
	{
		public boolean enforceMagicAttack = true;
		public int magicAttackMinimum = 1;
		public int magicAttackThreshold = -10;
	}

	/** Animation and pose IDs. Shared because they describe the game client, not a doctrine. */
	public static class Anims
	{
		public List<Integer> meleeAnimationIds = new ArrayList<>();
		/** PKP per block with a shield that has no codex amount of its own. Negative drains (down to zero). */
		public List<Integer> blockAnimationIds = new ArrayList<>();
		public List<Integer> rangedAnimationIds = new ArrayList<>();
		public List<Integer> targetCastAnimationIds = new ArrayList<>();
		public List<Integer> curseCastAnimationIds = new ArrayList<>();
		public List<Integer> selfCastAnimationIds = new ArrayList<>();
		public List<Integer> sitAnimationIds = new ArrayList<>();
		/**
		 * Special-attack animations, for the record only: specs are paid by the energy drop with the
		 * weapon equipped, never by animation. Nothing reads this list for PKP.
		 */
		public List<Integer> specialAnimationIds = new ArrayList<>();
	}

	/**
	 * Rules for the CRITICAL OVERLOAD lockdown. Shared so the punishment reads the same whichever god
	 * a player swore to - only the exempt item, which stays per-profile, differs.
	 */
	public static class Lockdown
	{
		/**
		 * Menu options that count as a teleport. Matched case-insensitively against the whole option,
		 * so "Rub" catches jewellery and "Break" catches tablets. Every one of them is removed during
		 * CRITICAL OVERLOAD except on an item in the profile's illegal-state exempt list.
		 */
		public List<String> teleportActions = new ArrayList<>();
	}

	/** VarPlayer and widget IDs the plugin reads. Shared for the same reason as {@link Anims}. */
	public static class Varps
	{
		public int specPercentVarpId = 300;
		public int specEnabledVarpId = 301;
		public int poisonVarpId = 102;
		public int reportWidgetGroup = 162;
		public int reportWidgetChild = 33;
		/** The bank interface; the PKP bar hides while it is open. Check with the Widget Inspector. */
		public int bankWidgetGroup = 12;
		public int bankWidgetChild = 1;
	}

	// ----------------------------------------------------------------- profile

	/** One faction's ruleset. */
	public static class Profile
	{
		public String faction;

		/** The words shown for this god on the oath screen. Authored here, not in code. */
		public Lore lore = new Lore();

		public Gear gear = new Gear();
		public Weapons weapons = new Weapons();
		public Ranged ranged = new Ranged();
		public Spec spec = new Spec();
		public Pool pool = new Pool();
		public Scaling scaling = new Scaling();
		public Regen regen = new Regen();
		public Restrict restrict = new Restrict();
		public Consumables consumables = new Consumables();
		public Overcharge overcharge = new Overcharge();
		public Pacifist pacifist = new Pacifist();
	}

	/**
	 * What the oath screen and side panel call one god. Both fields are optional: a blank one falls
	 * back to the built-in text on {@link Faction}.
	 */
	public static class Lore
	{
		/** Overrides the name on the card. Leave blank to use the faction's own name. */
		public String displayName = "";

		/** The one word under the name: ORDER, BALANCE, CHAOS, DARKNESS. Upper-cased on draw. */
		public String epithet = "";
	}

	public static class Gear
	{
		public List<String> magicGearExceptions = new ArrayList<>();
		/** This god's shields - armour like {@link #magicGearExceptions}, listed apart as shields. */
		public List<String> shields = new ArrayList<>();
		public List<String> magicGearForceBlock = new ArrayList<>();
	}

	public static class Weapons
	{
		/**
		 * Weapons this god refuses, by name or id - the weapon twin of
		 * {@link Gear#magicGearForceBlock}.
		 *
		 * <p>Beats every allow-list, so a weapon named here stays blocked even if it is also a
		 * listed exception, a ranged weapon or a spec weapon. It is how one god
		 * bars another's signature weapon without disturbing the magic-attack gate that governs
		 * everything else.
		 *
		 * <p>The one thing it loses to is {@link Shared#questItems}.
		 */
		public List<String> blockedWeapons = new ArrayList<>();

		public List<String> weaponExceptions = new ArrayList<>();
		public int weaponExceptionDefaultPkp = 50;
		public Map<String, Integer> pkpWeapons = new LinkedHashMap<>();
	}

	public static class Ranged
	{
		public List<String> rangedWeapons = new ArrayList<>();
		public boolean rangedRestoreEnabled = true;
		public int rangedRestore = 33;
	}

	public static class Spec
	{
		public int illegalClearSeconds = 6;
		public boolean illegalRepeatActions = true;
		public boolean bigMoveTriggers = true;
	}

	public static class Pool
	{
		/**
		 * This god's own worn spell costs, in the same shape as {@link Shared#wornSpellCosts} and
		 * added to it - the god capes, which only discount their own god's spell.
		 */
		public Map<String, Map<String, Integer>> wornSpellCosts = new LinkedHashMap<>();

		public int maxPkp = 100;
		public int combatSpellCost = 33;
		public int curseSpellCost = 25;
		public List<String> curseSpells = new ArrayList<>();
		public int meleeRestore = 50;
		/**
		 * PKP gained each time a block animation plays (see {@link Anims#blockAnimationIds}). 0 turns
		 * it off for this god. Never overcharges and never causes an overload.
		 */
		public int blockRestore = 0;
		public boolean poisonCostEnabled = true;
		/** While poisoned, spells and PKP costs are this much MORE expensive (50 = 1.5x). */
		public int poisonCostPercent = 50;
		/** While poisoned, PKP gained from consumables and specs is cut by this much (100 = none). */
		public int poisonRestorePercent = 100;

		/**
		 * Equipment that raises the ceiling while it is worn, as {@code name -> extra PKP}.
		 *
		 * <p>Per profile, because the point of it is that the item has to match the god: the holy
		 * book is Saradomin's answer and nobody else's. An item not named on this god's sheet does
		 * nothing for them, which is what keeps the Book of War and the Book of Law - Bandos's and
		 * Armadyl's - worth nothing to any of the four.
		 *
		 * <p>The bonus moves the overcharge ceiling with it, since that is defined as the maximum
		 * plus the headroom. Taking the item off lowers the maximum again, and a pool left above the
		 * new maximum behaves exactly like an overcharged one.
		 */
		public Map<String, Integer> maxPkpItems = new LinkedHashMap<>();
	}

	public static class Scaling
	{
		public boolean magicScalingEnabled;
		public int magicBonus50 = 10;
		public int magicBonus75 = 10;
		public int magicBonus85 = 10;
		public int magicBonus88 = 0;
		public int magicBonus90 = 10;
		public int magicBonus95 = 5;
		public int magicBonus99 = 5;
	}

	public static class Regen
	{
		public boolean oocRegenEnabled = true;

		/**
		 * How long out of combat before the pool starts refilling, in game ticks.
		 *
		 * <p>Ticks rather than seconds because that is the unit the game runs on and the unit a
		 * player counts in; seconds could not even express it once this became 4.2s, and a
		 * fractional "4.2 seconds" is a number nothing in the client would ever show you.
		 */
		public int oocThresholdTicks = 7;

		/**
		 * How long out of combat before OVERLOAD lapses on its own, in game ticks.
		 *
		 * <p>Was a hard-coded constant in the plugin and a second hard-coded copy in the rulebook
		 * generator, which is exactly the arrangement that lets a page and the thing it documents
		 * drift apart. Authored once, read by both.
		 */
		public int overloadClearTicks = 7;

		public int oocRestoreSeconds = 10;
		public boolean sitDoublesRegen = true;
	}

	public static class Restrict
	{
		/**
		 * Spells only this god may cast. Every other god is blocked from them, automatically: a spell
		 * is named once, on the sheet of the god it belongs to, and the plugin derives each faction's
		 * block list by unioning the other three. Nothing here has to be repeated as a denial, and
		 * moving a spell between gods is a single edit.
		 *
		 * <p>A god with an empty list simply owns no spells and is blocked from every other god's.
		 * Spell names are matched case-insensitively against the spellbook name, so they must be
		 * spelled the way the game spells them - {@code Iban Blast}, not {@code Iban's Blast}.
		 */
		public List<String> godSpells = new ArrayList<>();

		public boolean overloadBlocksAttack = true;
		public boolean blockFoodWhenOverloaded = true;
		public boolean blockPotionsWhenDepleted = true;
		public List<String> consumableExceptions = new ArrayList<>();
		public boolean illegalDefaultUse = true;
		public boolean blockCastWhileSeated = true;

		/**
		 * The twin of {@link #blockCastWhileSeated}, for the other half of combat.
		 *
		 * <p>Sitting already suppressed casting, because the sit pose eats the cast animation. The
		 * same is true of swinging at something: the pose means no attack animation plays, so a
		 * seated attack was a way to act without the plugin ever seeing the animation it keys off.
		 * Separately authored rather than folded into the cast flag, because they are two rules - a
		 * pack may well want seated casting barred and seated melee left alone, or the reverse.
		 */
		public boolean blockAttackWhileSeated = true;

		public List<String> restrictionExemptItems = new ArrayList<>();
	}

	public static class Consumables
	{
		public Map<String, Integer> pkpRestoreItems = new LinkedHashMap<>();
		public List<Effect> consumableEffects = new ArrayList<>();
	}

	public static class Overcharge
	{
		public boolean overchargeEnabled;
		public int overchargeHeadroom = 25;
		public List<String> overchargeItems = new ArrayList<>();
	}

	public static class Pacifist
	{
		public List<String> pacifistItems = new ArrayList<>();
	}

	/**
	 * One piece of quest equipment, and optionally the quests that make it one.
	 *
	 * <p>With {@link #quests} empty the item is unconditional: it overrides every equipment rule for
	 * the whole run, which is right for gear a quest leaves you holding for good.
	 *
	 * <p>With quests named, the override only applies while <b>at least one of them is in
	 * progress</b> - started and not yet finished. Before you start it, and the moment you finish
	 * it, the item stops being a quest item and falls back to the ordinary rules, so a quest weapon
	 * is a tool for the quest rather than a permanent way around the gate.
	 *
	 * <p>Several quests on one item is the reason this is a list: Silverlight is wanted by Demon
	 * Slayer and again by Shadow of the Storm, and naming both on the one entry is how that is
	 * said without repeating the item. Any one of them being in progress is enough.
	 *
	 * <p>Names must match the game's own quest names, which is what {@code net.runelite.api.Quest}
	 * is keyed on. A name the client does not know is logged once and then ignored, which leaves the
	 * item conditional on the quests that did resolve - or, if none did, never allowed.
	 */
	public static class QuestItem
	{
		public String item;

		public List<String> quests = new ArrayList<>();

		public QuestItem()
		{
		}

		public QuestItem(String item, List<String> quests)
		{
			this.item = item;
			this.quests = quests == null ? new ArrayList<>() : quests;
		}

		public boolean unconditional()
		{
			return quests == null || quests.isEmpty();
		}
	}

	/**
	 * A spec weapon or consumable and what it does to the bar.
	 *
	 * <p>{@code delta} is PKP gained (+) or removed (-). {@code effects} holds the tokens the
	 * plugin's effect parser understands, joined with {@code +}: {@code F<n>s}/{@code F<n>a} freeze
	 * for n seconds / attacks, {@code O<n>s}/{@code O<n>a} overload immunity, {@code D<n>s}/
	 * {@code D<n>a} depletion immunity, {@code R<gain>/<loss>} a coin flip for +gain or -loss,
	 * {@code CO}/{@code CD} to clear an active overload/depletion, {@code Z<n>s} freeze PKP at once
	 * for n seconds (after this item's own PKP lands), {@code G<pct>/<n>} and {@code S<pct>/<n>} PKP
	 * gained / spent at pct percent for n seconds, {@code KO} critical overload and {@code DP}
	 * forced depletion that breaks depletion immunity. Unknown tokens are ignored.
	 */
	public static class Effect
	{
		public String name;
		public int delta;
		public List<String> effects = new ArrayList<>();
	}

	/**
	 * Alcoholic drinks. Every sip cuts the PKP gained from melee, ranged and blocking by
	 * {@link #perSipPercent}, up to {@link #maxSips} sips stacked, for {@link #seconds} after the last
	 * sip. Each sip restarts the timer; sips beyond the cap only restart it.
	 */
	public static class Alcohol
	{
		public int perSipPercent = 10;
		/**
		 * PKP each sip costs (negative) or gives. A drink that has its own amount in a god's
		 * {@link Consumables#pkpRestoreItems} uses that instead - Wizard's mind bomb keeps its +50.
		 */
		public int pkpPerSip = 0;
		public int maxSips = 5;
		public int seconds = 30;
		public List<String> items = new ArrayList<>();
	}

	/**
	 * One weapon and the spells that keep its freeze alive.
	 *
	 * <p>{@code weapon} is matched the way every other entry is - by item id when it is a number and
	 * by lower-cased name otherwise. {@code spells} are spell names as the client spells them; the
	 * weapon's own melee attack always sustains, so a melee-only pairing can leave the list empty.
	 */
	public static class SustainedFreeze
	{
		public String weapon;
		public List<String> spells = new ArrayList<>();
	}
}

package com.battlemage;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Stroke;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.geom.Path2D;
import java.awt.geom.Rectangle2D;
import java.awt.geom.RoundRectangle2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A row of square badges for the PKP effects that are currently running, each drawn with a symbol instead of
 * a text label:
 * <ul>
 *   <li>snowflake - the PKP bar is frozen</li>
 *   <li>shield with an up chevron - overload immunity</li>
 *   <li>shield with a down chevron - depletion immunity</li>
 * </ul>
 * The countdown sits along the bottom of the badge. When an effect is running on a seconds timer AND an
 * attack count at the same time, the seconds show along the bottom and the remaining attacks move into a
 * corner badge, so neither is squeezed.
 *
 * It anchors bottom-left so it stacks with the PKP bar; drag it in overlay-edit mode to sit exactly above the
 * bar. Badge size is configurable and everything inside scales with it. Each badge uses the same colour that
 * effect paints onto the bar's border, and breathes on the same pulse as the bar frame, so a badge and its
 * border segment always read as the same effect.
 */
class EffectTimerOverlay extends Overlay
{
	private final BattleMagePlugin plugin;
	private final Appearance look;

	@Inject
	EffectTimerOverlay(BattleMagePlugin plugin, Appearance look)
	{
		this.plugin = plugin;
		this.look = look;
		setPosition(OverlayPosition.BOTTOM_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setMovable(true);
		setSnappable(true);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!look.showEffectTimers())
		{
			return null;
		}
		final List<BattleMagePlugin.ActiveEffect> fx = plugin.activeEffects();
		if (fx.isEmpty())
		{
			return null;
		}

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

		final int size = look.effectIconSize();
		final int gap = Math.max(3, size / 8);

		// the exact pulse curve the bar frame and the state text use
		final double pulse = look.barPulse()
			? 0.6 + 0.4 * (0.5 + 0.5 * Math.sin(System.currentTimeMillis() / 320.0))
			: 1.0;

		int x = 0;
		for (BattleMagePlugin.ActiveEffect e : fx)
		{
			Graphics2D cell = (Graphics2D) g.create();
			try
			{
				cell.translate(x, 0);
				drawBadge(cell, e, size, pulse);
			}
			finally
			{
				cell.dispose();
			}
			x += size + gap;
		}

		return new Dimension(fx.size() * size + (fx.size() - 1) * gap, size);
	}

	/** Draws one square badge into the region (0,0)-(size,size) of the supplied graphics. */
	private void drawBadge(Graphics2D g, BattleMagePlugin.ActiveEffect e, int size, double pulse)
	{
		final Color c = e.color;
		final int alpha = clamp((int) Math.round(255 * pulse));
		final float corner = size * 0.22f;
		final RoundRectangle2D box = new RoundRectangle2D.Float(1f, 1f, size - 2f, size - 2f, corner, corner);

		// dark body, then a faint tint so the whole badge carries the effect's hue
		g.setColor(new Color(0, 0, 0, 215));
		g.fill(box);
		g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), 46));
		g.fill(box);

		// pulsing border in the effect colour - same colour as this effect's segment on the bar.
		// An armed-but-not-started effect gets a dashed border and a dimmed symbol, so a freeze waiting
		// on your next attack reads differently from one that is already locking the bar.
		final float bw = Math.max(2f, size / 16f);
		g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha));
		g.setStroke(e.pending
			? new BasicStroke(bw, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 10f,
				new float[]{Math.max(3f, size / 7f), Math.max(3f, size / 9f)}, 0f)
			: new BasicStroke(bw));
		g.draw(box);

		final boolean drunk = e.kind == BattleMagePlugin.EffectKind.DRUNK;
		final String secs = e.secondsText();
		final String atks = drunk ? "" : e.attacksText();
		// seconds take the bottom line when present; a lone attack count takes it instead
		final String bottom = !secs.isEmpty() ? secs : atks;
		// only when BOTH are running does the attack count get pushed into the corner
		final boolean cornerBadge = !secs.isEmpty() && !atks.isEmpty();
		final boolean hasBottom = !bottom.isEmpty();

		// the symbol rides higher and shrinks a little when it has to share the square with a countdown;
		// the beer mug sits a touch lower and smaller still, to leave room for its sip count above it
		final double symY = drunk ? size * 0.51 : size * (hasBottom ? 0.40 : 0.50);
		final double symR = drunk ? size * 0.145 : size * (hasBottom ? 0.23 : 0.30);
		g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), e.pending ? 130 : 255));
		g.setStroke(new BasicStroke(Math.max(1.8f, size / 15f), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		drawSymbol(g, e, size / 2.0, symY, symR);

		if (drunk && e.stacks > 0)
		{
			// the sip count, centred above the mug
			final String n = Integer.toString(e.stacks);
			g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, Math.max(9, (int) Math.round(size * 0.26))));
			final FontMetrics fm = g.getFontMetrics();
			final int tx = (size - fm.stringWidth(n)) / 2;
			final int ty = Math.max(2, size / 14) + fm.getAscent() - 1;
			g.setColor(new Color(0, 0, 0, 235));
			g.drawString(n, tx + 1, ty + 1);
			g.setColor(Color.WHITE);
			g.drawString(n, tx, ty);
		}

		if (hasBottom)
		{
			g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, Math.max(9, (int) Math.round(size * 0.27))));
			final FontMetrics fm = g.getFontMetrics();
			final int tx = (size - fm.stringWidth(bottom)) / 2;
			final int ty = size - Math.max(3, size / 12) - fm.getDescent();
			g.setColor(new Color(0, 0, 0, 235));
			g.drawString(bottom, tx + 1, ty + 1);
			g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), e.pending ? 160 : 255));
			g.drawString(bottom, tx, ty);
		}

		if (cornerBadge)
		{
			drawCornerCount(g, e.attacks, size, c);
		}
	}

	/** Small circular count in the badge's top-right, used when seconds and attacks run at the same time. */
	private void drawCornerCount(Graphics2D g, int count, int size, Color c)
	{
		final int d = Math.max(12, (int) Math.round(size * 0.42));
		final int bx = size - d - 1;
		final int by = 1;

		g.setColor(new Color(0, 0, 0, 240));
		g.fillOval(bx, by, d, d);
		g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), 255));
		g.setStroke(new BasicStroke(Math.max(1.5f, size / 24f)));
		g.drawOval(bx, by, d, d);

		final String t = Integer.toString(count);
		g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, Math.max(8, (int) Math.round(d * 0.6))));
		final FontMetrics fm = g.getFontMetrics();
		g.setColor(Color.WHITE);
		g.drawString(t, bx + (d - fm.stringWidth(t)) / 2, by + (d + fm.getAscent() - fm.getDescent()) / 2);
	}

	// ---------------------------------------------------------------- symbols

	private void drawSymbol(Graphics2D g, BattleMagePlugin.ActiveEffect e, double cx, double cy, double r)
	{
		switch (e.kind)
		{
			case DRUNK:
				drawBeer(g, cx, cy, r);
				break;
			case SURGE:
				drawLabel(g, e.label, cx, cy, r);
				break;
			case FREEZE:
				drawSnowflake(g, cx, cy, r);
				break;
			case OVERLOAD_IMMUNE:
				drawShieldChevron(g, cx, cy, r, true);
				break;
			case DEPLETION_IMMUNE:
			default:
				drawShieldChevron(g, cx, cy, r, false);
				break;
		}
	}

	/** A beer mug: a gold body with a frothy white head spilling over the rim, and a handle. */
	private void drawBeer(Graphics2D g, double cx, double cy, double r)
	{
		final double w = r * 1.5;
		final double h = r * 1.75;
		final double l = cx - w / 2 - r * 0.22;
		final double t = cy - h / 2 + r * 0.2;
		final Color gold = g.getColor();
		final Stroke stroke = g.getStroke();
		// handle, then the body over it
		g.setStroke(new BasicStroke((float) Math.max(1.6, r * 0.28)));
		g.draw(new RoundRectangle2D.Double(l + w - r * 0.25, t + h * 0.22, r * 0.75, h * 0.5, r * 0.5, r * 0.5));
		g.fill(new RoundRectangle2D.Double(l, t, w, h, r * 0.3, r * 0.3));
		// darker glass edge so the body reads against the gold tint
		g.setStroke(new BasicStroke((float) Math.max(1.0, r * 0.12)));
		g.setColor(new Color(90, 55, 0, gold.getAlpha()));
		g.draw(new RoundRectangle2D.Double(l, t, w, h, r * 0.3, r * 0.3));
		// the head: three bubbles of foam riding over the rim
		g.setColor(new Color(255, 250, 235, gold.getAlpha()));
		final double fr = r * 0.42;
		for (int i = 0; i < 3; i++)
		{
			double fx = l + w * (0.18 + i * 0.32);
			g.fill(new Ellipse2D.Double(fx - fr, t - fr * 0.9 + (i == 1 ? -fr * 0.25 : 0), fr * 2, fr * 1.8));
		}
		g.setColor(gold);
		g.setStroke(stroke);
	}

	/** Text in place of a symbol, sized to the badge - used for a multiplier such as "x2". */
	private void drawLabel(Graphics2D g, String text, double cx, double cy, double r)
	{
		if (text == null || text.isEmpty())
		{
			return;
		}
		g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, Math.max(9, (int) Math.round(r * (text.length() > 2 ? 1.1 : 1.45)))));
		final FontMetrics fm = g.getFontMetrics();
		g.drawString(text, (float) (cx - fm.stringWidth(text) / 2.0), (float) (cy + (fm.getAscent() - fm.getDescent()) / 2.0));
	}

	/** Six-spoke snowflake with barbed tips. */
	private void drawSnowflake(Graphics2D g, double cx, double cy, double r)
	{
		for (int i = 0; i < 3; i++)
		{
			double a = Math.toRadians(i * 60 + 90);
			double dx = Math.cos(a) * r;
			double dy = Math.sin(a) * r;
			g.draw(new Line2D.Double(cx - dx, cy - dy, cx + dx, cy + dy));
		}
		final double barb = r * 0.36;
		for (int i = 0; i < 6; i++)
		{
			double a = Math.toRadians(i * 60 + 90);
			double tx = cx + Math.cos(a) * r * 0.58;
			double ty = cy + Math.sin(a) * r * 0.58;
			for (int s = -1; s <= 1; s += 2)
			{
				double ba = a + s * Math.toRadians(50);
				g.draw(new Line2D.Double(tx, ty, tx + Math.cos(ba) * barb, ty + Math.sin(ba) * barb));
			}
		}
	}

	/** Shield with a chevron inside: pointing up for overload immunity, down for depletion immunity. */
	private void drawShieldChevron(Graphics2D g, double cx, double cy, double r, boolean up)
	{
		final double w = r * 1.62;
		final double h = r * 1.92;
		final double l = cx - w / 2;
		final double rt = cx + w / 2;
		final double t = cy - h / 2;
		final double b = cy + h / 2;

		Path2D shield = new Path2D.Double();
		shield.moveTo(l, t);
		shield.lineTo(rt, t);
		shield.lineTo(rt, t + h * 0.42);
		shield.quadTo(rt, b - h * 0.08, cx, b);
		shield.quadTo(l, b - h * 0.08, l, t + h * 0.42);
		shield.closePath();
		g.draw(shield);

		final double k = r * 0.44;
		final double my = cy - h * 0.05;
		Path2D chevron = new Path2D.Double();
		if (up)
		{
			chevron.moveTo(cx - k, my + k * 0.55);
			chevron.lineTo(cx, my - k * 0.55);
			chevron.lineTo(cx + k, my + k * 0.55);
		}
		else
		{
			chevron.moveTo(cx - k, my - k * 0.55);
			chevron.lineTo(cx, my + k * 0.55);
			chevron.lineTo(cx + k, my - k * 0.55);
		}
		g.draw(chevron);
	}

	private static int clamp(int v)
	{
		return Math.max(0, Math.min(255, v));
	}
}

package com.battlemage;

import java.awt.Color;

/**
 * The four god factions that can be sworn to. Whichever is in force selects the ruleset in the
 * bundled {@link ContentPack} that the plugin enforces; the side panel can change it at any time.
 *
 * <p>The name and epithet here are <b>fallbacks only</b>. The words the oath screen actually
 * shows are authored per faction in the codex under {@code profiles.<GOD>.lore} and reached through
 * {@link Rules#lore(Faction)}; these constants are what fills in for a field left blank there.
 * Colours are not authorable and live here for good.
 */
public enum Faction
{
	SARADOMIN(
		"Saradomin",
		"Order",
		new Color(0x3F87DC)),

	GUTHIX(
		"Guthix",
		"Balance",
		new Color(0x3FA96A)),

	ZAMORAK(
		"Zamorak",
		"Chaos",
		new Color(0xCE4038)),

	ZAROS(
		"Zaros",
		"Darkness",
		new Color(0x8367BE)),

	/**
	 * Not a god: the PKP system on its own, taken from the Wise Old Man by a player who was sworn
	 * to one. Every PKP rule applies and every god's spells stay barred, but nothing restricts
	 * gear, weapons or the cannon. Gold, like the toolbar icon and the shrine before any oath.
	 */
	FACTIONLESS(
		"Faction-less",
		"Unbound",
		new Color(0xE3B93B));

	/** The four gods, in the order the oath screen shows them - never {@link #FACTIONLESS}. */
	static final Faction[] GODS = {SARADOMIN, GUTHIX, ZAMORAK, ZAROS};

	private final String displayName;
	private final String epithet;
	private final Color primary;

	Faction(String displayName, String epithet, Color primary)
	{
		this.displayName = displayName;
		this.epithet = epithet;
		this.primary = primary;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	/** Fallback for the one word under the name on the god card, when the codex leaves it blank. */
	public String getEpithet()
	{
		return epithet;
	}


	/** One of the four gods, rather than the faction-less PKP system. */
	public boolean isGod()
	{
		return this != FACTIONLESS;
	}

	/** The faction's crest and accent colour. */
	public Color getPrimary()
	{
		return primary;
	}


	public static Faction byName(String raw)
	{
		if (raw != null)
		{
			for (Faction f : values())
			{
				if (f.name().equalsIgnoreCase(raw.trim()))
				{
					return f;
				}
			}
		}
		return null;
	}
}

package com.battlemage;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.Area;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

/**
 * The X-Ray aura: a glowing ring on the ground under your character, in your god's colour. It is
 * drawn over the scene, so it stays visible through walls and scenery (the Soul aura is the in-world
 * version, see {@link SoulAura}).
 *
 * <p>The ring is built from points around the player in the game world and projected onto the
 * screen, so it lies flat on the ground, follows the terrain and turns with the camera. The
 * character's own outline is cut out of it, so the ring reads as being underneath them rather than
 * painted across their legs. Only you can see it: nothing is sent anywhere or changed in the game.
 */
@Singleton
class FactionAuraOverlay extends Overlay
{
	/** Ring radius in local units (a tile is 128). */
	private static final int RADIUS = 72;
	/** Points around the ring: enough to look round at any zoom. */
	private static final int SEGMENTS = 48;
	/** One slow breath of the glow, and one full turn of the bright arcs. */
	private static final double PULSE_MS = 2400.0;
	private static final double SPIN_MS = 9000.0;

	private final Client client;
	private final Oath oath;
	private final Appearance look;

	@Inject
	FactionAuraOverlay(Client client, Oath oath, Appearance look)
	{
		this.client = client;
		this.oath = oath;
		this.look = look;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(OverlayPriority.LOW);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Faction faction = oath.getFaction();
		Player me = client.getLocalPlayer();
		if (look.auraMode() != AuraMode.XRAY || faction == null || me == null
			|| client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}
		LocalPoint at = me.getLocalLocation();
		if (at == null)
		{
			return null;
		}
		int plane = client.getTopLevelWorldView().getPlane();

		Polygon outer = ring(at, plane, RADIUS, 0.0);
		Polygon inner = ring(at, plane, (int) (RADIUS * 0.62), 0.0);
		if (outer == null || inner == null)
		{
			return null;
		}

		long now = System.currentTimeMillis();
		double breath = 0.5 + 0.5 * Math.sin(now / PULSE_MS * 2 * Math.PI);
		Color c = faction.getPrimary();

		Shape oldClip = g.getClip();
		Object oldAa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		// cut the character out, so the ring sits under them
		Shape hull = me.getConvexHull();
		if (hull != null)
		{
			Rectangle view = new Rectangle(0, 0, client.getCanvasWidth(), client.getCanvasHeight());
			Area clip = new Area(oldClip != null ? oldClip : view);
			clip.subtract(new Area(hull));
			g.setClip(clip);
		}

		// a soft disc: the band between the inner and outer ring, lightly filled
		Area band = new Area(outer);
		band.subtract(new Area(inner));
		g.setColor(alpha(c, (int) (45 + 30 * breath)));
		g.fill(band);
		g.setColor(alpha(c, (int) (18 + 12 * breath)));
		g.fill(inner);

		// the glow, then the bright rim on top of it
		g.setStroke(new BasicStroke(7f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(alpha(c, (int) (50 + 40 * breath)));
		g.draw(outer);
		g.setStroke(new BasicStroke(2.2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(alpha(c.brighter(), (int) (190 + 50 * breath)));
		g.draw(outer);
		g.setStroke(new BasicStroke(1.2f));
		g.setColor(alpha(c, (int) (110 + 40 * breath)));
		g.draw(inner);

		// three short bright arcs that turn slowly around the rim
		double spin = (now % (long) SPIN_MS) / SPIN_MS * 2 * Math.PI;
		g.setStroke(new BasicStroke(3f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(alpha(Color.WHITE, (int) (120 + 60 * breath)));
		for (int k = 0; k < 3; k++)
		{
			Polygon arc = arc(at, plane, RADIUS, spin + k * 2 * Math.PI / 3, Math.PI / 7);
			if (arc != null)
			{
				g.drawPolyline(arc.xpoints, arc.ypoints, arc.npoints);
			}
		}

		g.setClip(oldClip);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, oldAa);
		return null;
	}

	/** A full ring of the given radius around a point, projected to the screen; null if off screen. */
	private Polygon ring(LocalPoint at, int plane, int radius, double start)
	{
		return arc(at, plane, radius, start, 2 * Math.PI, SEGMENTS);
	}

	private Polygon arc(LocalPoint at, int plane, int radius, double start, double sweep)
	{
		return arc(at, plane, radius, start, sweep, 8);
	}

	private Polygon arc(LocalPoint at, int plane, int radius, double start, double sweep, int steps)
	{
		Polygon p = new Polygon();
		for (int i = 0; i <= steps; i++)
		{
			double a = start + sweep * i / steps;
			LocalPoint lp = at.plus((int) Math.round(Math.cos(a) * radius), (int) Math.round(Math.sin(a) * radius));
			Point s = Perspective.localToCanvas(client, lp, plane);
			if (s == null)
			{
				return null;
			}
			p.addPoint(s.getX(), s.getY());
		}
		return p;
	}

	private static Color alpha(Color c, int a)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), Math.max(0, Math.min(255, a)));
	}
}

package com.battlemage;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.util.EnumMap;
import java.util.Locale;
import java.util.Map;
import javax.imageio.ImageIO;
import lombok.extern.slf4j.Slf4j;

/**
 * Draws the crest for each god.
 *
 * <p>Each faction looks for its own image on the classpath at {@code /sigils/<faction>.png} -
 * {@code saradomin.png}, {@code guthix.png}, {@code zamorak.png}, {@code zaros.png} - and draws that
 * if it finds one. Drop a file in {@code src/main/resources/sigils/} and every crest in the plugin
 * picks it up at once: the oath cards and the side panel.
 *
 * <p>All four gods ship with artwork. A god whose image is missing shows just the shared ring.
 */
@Slf4j
final class FactionSigils
{
	/** Where a faction's artwork lives on the classpath. */
	private static final String SIGIL_PATH = "/sigils/%s.png";

	/**
	 * Loaded artwork, keyed by faction. A key present with a null value means "looked, found
	 * nothing" - the lookup happens once per faction per session, not once per frame.
	 */
	private static final Map<Faction, BufferedImage> ART = new EnumMap<>(Faction.class);

	private FactionSigils()
	{
	}

	/**
	 * The faction's artwork, or null when its image is missing.
	 *
	 * <p>Looked up under the lower-case faction name first and the upper-case one second, so a file
	 * named either way is found. A file that fails to decode is treated as absent and logged once.
	 */
	private static synchronized BufferedImage art(Faction faction)
	{
		if (ART.containsKey(faction))
		{
			return ART.get(faction);
		}
		BufferedImage loaded = null;
		for (String name : new String[]{faction.name().toLowerCase(Locale.ROOT), faction.name()})
		{
			try (InputStream in = FactionSigils.class.getResourceAsStream(
				String.format(SIGIL_PATH, name)))
			{
				if (in != null)
				{
					loaded = ImageIO.read(in);
					if (loaded != null)
					{
						break;
					}
				}
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Could not read the {} sigil; showing the ring only", faction, e);
			}
		}
		ART.put(faction, loaded);
		return loaded;
	}

	/**
	 * One line naming which gods found their artwork.
	 *
	 * <p>Logged once at start-up, so "did my PNG get picked up?" has an answer. Resources are packed
	 * at build time - a file dropped in beside a running client is not in its jar.
	 */
	static String crestReport()
	{
		StringBuilder sb = new StringBuilder();
		for (Faction f : Faction.GODS)
		{
			sb.append(sb.length() == 0 ? "" : "  ")
				.append(f.name().toLowerCase(Locale.ROOT))
				.append('=')
				.append(art(f) != null ? "found" : "MISSING");
		}
		return sb.toString();
	}

	/** Draws a faction crest centred in a square of {@code size} at {@code (x, y)}. */
	static void drawFaction(Graphics2D g, Faction faction, int x, int y, int size)
	{
		Graphics2D gg = (Graphics2D) g.create();
		gg.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		gg.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
			RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		gg.translate(x, y);
		double s = size / 48.0;
		gg.scale(s, s);

		// Every crest sits inside the same ring, so the four read as one set.
		gg.setColor(alpha(faction.getPrimary(), 110));
		gg.setStroke(new BasicStroke(1.4f));
		gg.draw(new Ellipse2D.Double(2, 2, 44, 44));

		BufferedImage img = art(faction);
		if (img != null)
		{
			// Fitted to a 34-unit box inside the 48-unit crest space, aspect preserved.
			final double box = 34.0;
			double scale = Math.min(box / img.getWidth(), box / img.getHeight());
			int iw = (int) Math.round(img.getWidth() * scale);
			int ih = (int) Math.round(img.getHeight() * scale);
			gg.drawImage(img, 24 - iw / 2, 24 - ih / 2, iw, ih, null);
		}
		gg.dispose();
	}

	// ------------------------------------------------------------------ colour

	static Color alpha(Color c, int a)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), Math.max(0, Math.min(255, a)));
	}
}

package com.battlemage;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * When illegal behaviour is flagged (a special-attack-only weapon auto-attacked), screams a diagonal
 * hazard-tape "ILLEGAL BEHAVIOR DETECTED" warning across the 3D game viewport only (interfaces stay clear).
 * Clears once the plugin reports the player has been out of combat long enough.
 */
class IllegalBehaviorOverlay extends Overlay
{
	private final Client client;
	private final BattleMagePlugin plugin;
	private final BattleMageConfig config;

	@Inject
	IllegalBehaviorOverlay(Client client, BattleMagePlugin plugin, BattleMageConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!plugin.illegalBehaviorActive())
		{
			return null;
		}

		int vx = client.getViewportXOffset();
		int vy = client.getViewportYOffset();
		int vw = client.getViewportWidth();
		int vh = client.getViewportHeight();
		if (vw <= 0 || vh <= 0)
		{
			vx = 0;
			vy = 0;
			vw = client.getCanvasWidth();
			vh = client.getCanvasHeight();
		}
		if (vw <= 0 || vh <= 0)
		{
			return null;
		}

		final long now = System.currentTimeMillis();
		final double flash = 0.55 + 0.45 * Math.abs(Math.sin(now / 180.0));

		Graphics2D gg = (Graphics2D) g.create();
		try
		{
			gg.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			gg.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			gg.setClip(new Rectangle(vx, vy, vw, vh));

			// red wash
			gg.setColor(new Color(150, 0, 0, (int) (90 * flash)));
			gg.fillRect(vx, vy, vw, vh);

			final int cx = vx + vw / 2;
			final int cy = vy + vh / 2;
			final int reach = (int) Math.hypot(vw, vh);

			gg.translate(cx, cy);
			gg.rotate(Math.toRadians(-45));

			// hazard stripes
			gg.setColor(new Color(0, 0, 0, (int) (150 * flash)));
			gg.fillRect(-reach, -reach, reach * 2, reach * 2);
			gg.setColor(new Color(255, 215, 0, (int) (220 * flash)));
			int band = 64;
			for (int yy = -reach; yy < reach; yy += band * 2)
			{
				gg.fillRect(-reach, yy, reach * 2, band);
			}

			// repeated warning text along the diagonals
			gg.setFont(new Font(Font.SANS_SERIF, Font.BOLD, Math.max(20, vw / 22)));
			FontMetrics fm = gg.getFontMetrics();
			String msg = "ILLEGAL BEHAVIOR DETECTED";
			int tw = fm.stringWidth(msg);
			int rowH = band * 2;
			int row = 0;
			for (int yy = -reach; yy < reach; yy += rowH, row++)
			{
				int startX = -reach - (row % 2) * (tw / 2);
				for (int xx = startX; xx < reach; xx += tw + 60)
				{
					gg.setColor(new Color(0, 0, 0, (int) (235 * flash)));
					gg.drawString(msg, xx + 2, yy + band - 14 + 2);
					gg.setColor(new Color(255, 30, 30, (int) (255 * flash)));
					gg.drawString(msg, xx, yy + band - 14);
				}
			}
		}
		finally
		{
			gg.dispose();
		}
		return null;
	}
}

package com.battlemage;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Paint;
import java.awt.RenderingHints;
import java.awt.geom.RoundRectangle2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * EarthBound-style level-up cards. Mirrors the PSI cast cards (slide in, dwell, dissolve) but enters from the
 * TOP-RIGHT corner of the screen - exactly opposite the cast cards' top-left - sliding in from the right. Each
 * card is themed to the skill that levelled, lingers a little longer than the cast cards, and they play ONE AT
 * A TIME: a card must fully fade before the next one appears.
 */
class LevelUpCardOverlay extends Overlay
{
	private static final long LIFE_MS = 3800L;   // longer than the cast cards' 2500ms
	private static final int CARD_H = 30;
	private static final int MARGIN = 8;          // same margin the cast cards use, but from the right edge

	private final Client client;
	private final BattleMagePlugin plugin;
	private final Appearance look;

	@Inject
	LevelUpCardOverlay(Client client, BattleMagePlugin plugin, Appearance look)
	{
		this.client = client;
		this.plugin = plugin;
		this.look = look;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!look.levelUpCards())
		{
			return null;
		}
		List<BattleMagePlugin.LevelCard> cards = plugin.getLevelCards();
		if (cards.isEmpty())
		{
			return null;
		}
		// only ever render the front card, and only once it has been started (by the game tick)
		BattleMagePlugin.LevelCard c = cards.get(0);
		if (c.startMs == 0L)
		{
			return null;
		}

		final long now = System.currentTimeMillis();
		double age = (now - c.startMs) / (double) LIFE_MS;
		if (age < 0 || age >= 1.0)
		{
			return null;
		}

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 15));
		final FontMetrics fm = g.getFontMetrics();

		// anchor to the game viewport's top-right (the scene area), so cards sit at the top of the play
		// area and clear the minimap / side UI rather than overlapping them
		int vx = client.getViewportXOffset();
		int vy = client.getViewportYOffset();
		int vw = client.getViewportWidth();
		if (vw <= 0)
		{
			vx = 0;
			vy = 0;
			vw = client.getCanvasWidth() > 0 ? client.getCanvasWidth() : 520;
		}
		final int rightEdge = vx + vw - MARGIN;

		double in = Math.min(1.0, age / 0.12);            // quick slide-in
		float alpha = (float) Math.max(0f, Math.min(1f, in * (1.0 - age) * 1.25));
		int slideY = (int) Math.round((1.0 - in) * -24);  // enters from above its landing spot

		String label = "\u25B2 " + c.skill + "  Lv " + c.level;
		int cardW = Math.max(150, fm.stringWidth(label) + 44);
		int x = rightEdge - cardW;                         // fixed landing x at the viewport's top-right
		int y = vy + MARGIN + slideY;

		Color col = c.color != null ? c.color : Color.WHITE;
		final Composite baseComposite = g.getComposite();
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));

		RoundRectangle2D box = new RoundRectangle2D.Float(x, y, cardW, CARD_H, 12, 12);
		g.setColor(new Color(0, 0, 0, 220));
		g.fill(box);

		// skill-coloured wash so the card takes on the skill's vibe
		Paint oldPaint = g.getPaint();
		g.setPaint(new GradientPaint(
			x, y, new Color(col.getRed(), col.getGreen(), col.getBlue(), 30),
			x + cardW, y, new Color(col.getRed(), col.getGreen(), col.getBlue(), 110)));
		g.fill(box);
		g.setPaint(oldPaint);

		// soft pulsing glow + border in the skill colour
		double blink = 0.6 + 0.4 * Math.sin(now / 200.0);
		int glowA = Math.max(0, Math.min(255, (int) Math.round(70 * blink)));
		g.setColor(new Color(col.getRed(), col.getGreen(), col.getBlue(), glowA));
		g.setStroke(new BasicStroke(4f));
		g.draw(new RoundRectangle2D.Float(x - 1, y - 1, cardW + 2, CARD_H + 2, 13, 13));
		g.setColor(new Color(col.getRed(), col.getGreen(), col.getBlue(), 240));
		g.setStroke(new BasicStroke(2f));
		g.draw(box);

		// label
		int tx = x + 12;
		int ty = y + CARD_H / 2 + fm.getAscent() / 2 - 2;
		g.setColor(new Color(0, 0, 0, 230));
		g.drawString(label, tx + 1, ty + 1);
		g.setColor(Color.WHITE);
		g.drawString(label, tx, ty);

		g.setComposite(baseComposite);
		return null;
	}
}

package com.battlemage;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * The god currently in force. There is exactly one, and it can be changed at any time.
 *
 * <p>Deliberately not a profile system: nothing is locked and nothing is per-character. A player
 * running two accounts swaps the god by hand when they log into the other one - the honour system
 * does the rest. That keeps the whole thing to one stored value instead of a list of records with
 * identities, names and an active pointer.
 *
 * <p>Stored in its own config group, away from {@link BattleMageConfig#GROUP}, so it never shows up as
 * a setting in the RuneLite panel.
 */
@Slf4j
@Singleton
public class Oath
{
	static final String GROUP = "battlemageoath";
	private static final String KEY_FACTION = "faction";

	private final ConfigManager configManager;

	private Faction faction;

	/**
	 * True between leaving a god and becoming faction-less in front of the Wise Old Man, so the
	 * "how to begin" prompts stay away for the moment the player is briefly unsworn.
	 */
	private volatile boolean ceremony;

	/** Called after any change that alters which rules apply, so the plugin can rebuild caches. */
	private Runnable changeListener = () ->
	{
	};

	@Inject
	public Oath(ConfigManager configManager)
	{
		this.configManager = configManager;
		load();
	}

	public void setChangeListener(Runnable listener)
	{
		this.changeListener = listener == null ? () ->
		{
		} : listener;
	}

	// ------------------------------------------------------------------ reading

	/** False until a god has been chosen; the plugin enforces nothing until then. */
	public boolean isSworn()
	{
		return faction != null;
	}

	boolean inCeremony()
	{
		return ceremony;
	}

	void setCeremony(boolean on)
	{
		ceremony = on;
	}

	public Faction getFaction()
	{
		return faction;
	}

	/** The {@link ContentPack#profiles} key to enforce, or null when no god is in force. */
	public String getRulesetKey()
	{
		return isSworn() ? faction.name() : null;
	}

	// ------------------------------------------------------------------ writing

	/** Swears to a god. Free to call at any time - this replaces whatever was chosen before. */
	public void swear(Faction next)
	{
		if (next == null || next == faction)
		{
			return;
		}
		faction = next;
		persist();
		log.debug("Sworn to {}", faction);
		changeListener.run();
	}

	/** Drops the oath entirely, so the oath screen reopens. */
	public void clear()
	{
		if (faction == null)
		{
			return;
		}
		faction = null;
		persist();
		changeListener.run();
	}

	// ---------------------------------------------------------------- storage

	private void load()
	{
		faction = Faction.byName(configManager.getConfiguration(GROUP, KEY_FACTION));
	}

	private void persist()
	{
		if (faction == null)
		{
			configManager.unsetConfiguration(GROUP, KEY_FACTION);
		}
		else
		{
			configManager.setConfiguration(GROUP, KEY_FACTION, faction.name());
		}
	}
}

package com.battlemage;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Inventory restriction visuals.
 * <ul>
 *   <li>While ILLEGAL BEHAVIOR is showing: a single translucent orange wash over the whole inventory
 *       (no per-item symbols), plus a bright-green outline around the exempt item(s) - the Cowbell amulet,
 *       the only one-click teleport during that state.</li>
 *   <li>Otherwise: the usual per-item "no" symbol over off-limit gear/weapons (red) and the state circles
 *       over food/potions blocked by overload/depletion.</li>
 * </ul>
 */
class OffLimitItemOverlay extends Overlay
{
	/** The inventory interface (group 149, child 0), by number rather than the retired WidgetInfo enum. */
	private static final int INVENTORY_GROUP = 149;

	// the worn-equipment interface group; item icons within it carry their worn item id
	private static final int EQUIPMENT_GROUP = 387;

	private final Client client;
	private final BattleMagePlugin plugin;
	private final Appearance look;

	@Inject
	OffLimitItemOverlay(Client client, BattleMagePlugin plugin, Appearance look)
	{
		this.client = client;
		this.plugin = plugin;
		this.look = look;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		// The appearance editor's CRITICAL sample shows these markers too, so their colours can be
		// judged without being in the state.
		if (plugin.lockdownActive() || look.sample() == Appearance.Sample.CRITICAL)
		{
			renderIllegal(g);
		}
		else
		{
			renderNormal(g);
		}
		if (plugin.showCowbellGauges())
		{
			renderCowbellGauges(g);
		}
		return null;
	}

	// ---------------------------------------------------------------- Cowbell gauges

	/** The two slim gauges either side of the Cowbell amulet: caught-below-empty left, caught-above-full right. */
	private void renderCowbellGauges(Graphics2D g)
	{
		List<Rectangle> bells = new ArrayList<>();
		Widget inv = client.getWidget(INVENTORY_GROUP, 0);
		if (inv != null && !inv.isHidden() && inv.getDynamicChildren() != null)
		{
			for (Widget item : inv.getDynamicChildren())
			{
				if (item != null && !item.isHidden() && BattleMagePlugin.isCowbell(item.getItemId()))
				{
					bells.add(item.getBounds());
				}
			}
		}
		Widget[] roots = client.getWidgetRoots();
		if (roots != null)
		{
			for (Widget root : roots)
			{
				findWornBell(root, 0, bells);
			}
		}
		double under = plugin.storedUnder() / BattleMagePlugin.SPILL_STORE_MAX;
		double over = plugin.storedOver() / BattleMagePlugin.SPILL_STORE_MAX;
		boolean underCooling = plugin.cowbellCooldown(-1) > 0;
		boolean overCooling = plugin.cowbellCooldown(1) > 0;
		Rectangle source = null;
		for (Rectangle b : bells)
		{
			if (b == null || b.width <= 0 || b.height <= 0)
			{
				continue;
			}
			if (source == null)
			{
				source = b;
			}
			drawGauge(g, b.x - 1, b.y + 2, b.height - 4, under, look.barColorLow(), underCooling);
			drawGauge(g, b.x + b.width - 6, b.y + 2, b.height - 4, over, look.barColorFull(), overCooling);
			drawTwinkle(g, b);
		}
		drawZap(g, source);
	}

	// ---------------------------------------------------------------- absorbing and releasing

	/** How long the amulet glints after it catches a spill. */
	private static final long SPARKLE_MS = 700L;

	/** When the amulet catches a spill, it glints in that side's colour. */
	private void drawTwinkle(Graphics2D g, Rectangle b)
	{
		long now = System.currentTimeMillis();
		long start = plugin.spillStartMs();
		int side = plugin.spillSide();
		long age = now - start;
		if (start == 0 || side == 0 || age < 0 || age >= SPARKLE_MS || !look.barExhaust())
		{
			return;
		}
		double life = 1.0 - age / (double) SPARKLE_MS;
		Color c = side > 0 ? look.barColorFull() : look.barColorLow();
		java.util.Random r = new java.util.Random(start * 17 + age / 90);
		for (int k = 0; k < 3; k++)
		{
			double phase = Math.sin((age / 90.0) + k * 2.1);
			double size = (2.5 + 2.5 * Math.abs(phase)) * life;
			if (size < 1)
			{
				continue;
			}
			int cx = b.x + 6 + r.nextInt(Math.max(1, b.width - 12));
			int cy = b.y + 6 + r.nextInt(Math.max(1, b.height - 12));
			int a = (int) Math.round(255 * life);
			g.setStroke(new BasicStroke(1.4f));
			g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), Math.min(255, a)));
			g.drawLine((int) (cx - size), cy, (int) (cx + size), cy);
			g.drawLine(cx, (int) (cy - size), cx, (int) (cy + size));
			g.setColor(new Color(255, 255, 255, Math.min(255, a)));
			g.fillOval(cx - 1, cy - 1, 2, 2);
		}
	}

	private static final long ZAP_MS = 420L;
	private static final long ZAP_SPARK_MS = 650L;

	/** A release: a bolt from the amulet into the PKP bar, throwing sparks where it lands. */
	private void drawZap(Graphics2D g, Rectangle bell)
	{
		long now = System.currentTimeMillis();
		long start = plugin.zapStartMs();
		long age = now - start;
		Rectangle bar = plugin.barScreenBounds();
		if (start == 0 || age < 0 || age >= ZAP_SPARK_MS || bar == null)
		{
			return;
		}
		// a release the worn amulet made on its own leaves from the player; one made by hand from the amulet
		double sx;
		double sy;
		net.runelite.api.Point from = plugin.zapFromPlayer() ? playerPoint(g) : null;
		if (from != null)
		{
			sx = from.getX();
			sy = from.getY();
		}
		else if (bell != null && !plugin.zapFromPlayer())
		{
			sx = bell.getCenterX();
			sy = bell.getCenterY();
		}
		else
		{
			return;
		}
		int side = plugin.zapSide();
		Color c = side > 0 ? look.barColorFull() : look.barColorLow();
		double ex = bar.x + bar.width * (side > 0 ? 0.75 : 0.25);
		double ey = bar.getCenterY();
		java.awt.Stroke old = g.getStroke();

		if (age < ZAP_MS)
		{
			double life = 1.0 - age / (double) ZAP_MS;
			java.util.Random r = new java.util.Random(start * 13 + age / 40);
			java.util.List<double[]> pts = new ArrayList<>();
			pts.add(new double[]{sx, sy});
			pts.add(new double[]{ex, ey});
			double spread = Math.hypot(ex - sx, ey - sy) / 6.0;
			for (int pass = 0; pass < 5; pass++)
			{
				java.util.List<double[]> next = new ArrayList<>();
				for (int i = 0; i < pts.size() - 1; i++)
				{
					double[] p0 = pts.get(i);
					double[] p1 = pts.get(i + 1);
					next.add(p0);
					next.add(new double[]{
						(p0[0] + p1[0]) / 2 + (r.nextDouble() - 0.5) * spread,
						(p0[1] + p1[1]) / 2 + (r.nextDouble() - 0.5) * spread});
				}
				next.add(pts.get(pts.size() - 1));
				pts = next;
				spread /= 2;
			}
			java.awt.geom.Path2D.Double path = new java.awt.geom.Path2D.Double();
			path.moveTo(pts.get(0)[0], pts.get(0)[1]);
			for (int i = 1; i < pts.size(); i++)
			{
				path.lineTo(pts.get(i)[0], pts.get(i)[1]);
			}
			int a = (int) Math.round(255 * Math.min(1.0, life * 1.6));
			g.setStroke(new BasicStroke(7f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), Math.min(255, a / 3)));
			g.draw(path);
			g.setStroke(new BasicStroke(3f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), Math.min(255, a)));
			g.draw(path);
			g.setStroke(new BasicStroke(1.2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.setColor(new Color(255, 255, 255, Math.min(255, a)));
			g.draw(path);
		}

		// sparks thrown from where the bolt hits
		double t = age / 1000.0;
		double life = 1.0 - age / (double) ZAP_SPARK_MS;
		java.util.Random r = new java.util.Random(start);
		for (int k = 0; k < 16; k++)
		{
			double ang = r.nextDouble() * Math.PI * 2;
			double speed = 60 + 160 * r.nextDouble();
			double px = ex + Math.cos(ang) * speed * t;
			double py = ey + Math.sin(ang) * speed * t + 260 * t * t;
			double d = 1.5 + 2.5 * life;
			g.setColor(new Color(
				k % 3 == 0 ? 255 : c.getRed(), k % 3 == 0 ? 255 : c.getGreen(), k % 3 == 0 ? 255 : c.getBlue(),
				Math.max(0, Math.min(255, (int) Math.round(255 * life)))));
			g.fill(new java.awt.geom.Ellipse2D.Double(px - d / 2, py - d / 2, d, d));
		}
		g.setStroke(old);
	}

	/** The middle of the player's character on screen, or null when it is not drawn. */
	private net.runelite.api.Point playerPoint(Graphics2D g)
	{
		net.runelite.api.Player me = client.getLocalPlayer();
		if (me == null)
		{
			return null;
		}
		return me.getCanvasTextLocation(g, "", me.getLogicalHeight() / 2);
	}

	private void findWornBell(Widget w, int depth, List<Rectangle> out)
	{
		if (w == null || depth > 8 || w.isHidden())
		{
			return;
		}
		if ((w.getId() >>> 16) == EQUIPMENT_GROUP && BattleMagePlugin.isCowbell(w.getItemId()))
		{
			out.add(w.getBounds());
		}
		for (Widget[] kids : new Widget[][]{w.getStaticChildren(), w.getDynamicChildren(), w.getNestedChildren()})
		{
			if (kids != null)
			{
				for (Widget k : kids)
				{
					findWornBell(k, depth + 1, out);
				}
			}
		}
	}

	/** A 4px-wide vertical gauge filling from the bottom; grey with a small red X while cooling down. */
	private static void drawGauge(Graphics2D g, int x, int y, int h, double frac, Color c, boolean cooling)
	{
		if (h < 6)
		{
			return;
		}
		if (cooling)
		{
			g.setColor(new Color(0, 0, 0, 170));
			g.fillRoundRect(x, y, 4, h, 3, 3);
			g.setColor(new Color(120, 120, 120, 230));
			g.fillRoundRect(x + 1, y + 1, 2, h - 2, 2, 2);
			int cx = x + 2;
			int cy = y + h / 2;
			g.setStroke(new BasicStroke(1.3f));
			g.setColor(new Color(0, 0, 0, 200));
			g.drawLine(cx - 3, cy - 3, cx + 3, cy + 3);
			g.drawLine(cx - 3, cy + 3, cx + 3, cy - 3);
			g.setColor(new Color(230, 30, 30));
			g.drawLine(cx - 2, cy - 2, cx + 2, cy + 2);
			g.drawLine(cx - 2, cy + 2, cx + 2, cy - 2);
			return;
		}
		double f = Math.max(0, Math.min(1, frac));
		g.setColor(new Color(0, 0, 0, 170));
		g.fillRoundRect(x, y, 4, h, 3, 3);
		int fh = (int) Math.round((h - 2) * f);
		if (fh > 0)
		{
			g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), f >= 1 ? 255 : 220));
			g.fillRoundRect(x + 1, y + 1 + (h - 2 - fh), 2, fh, 2, 2);
		}
		if (f >= 1)
		{
			double blink = 0.5 + 0.5 * Math.sin(System.currentTimeMillis() / 220.0);
			g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), (int) Math.round(60 + 120 * blink)));
			g.setStroke(new BasicStroke(1.5f));
			g.drawRoundRect(x - 1, y - 1, 6, h + 2, 4, 4);
		}
	}

	// ---------------------------------------------------------------- ILLEGAL state

	/** Orange wash over the inventory AND the worn-equipment panel, with the exempt item(s) outlined. */
	private void renderIllegal(Graphics2D g)
	{
		final Color s = look.illegalInventoryShade();
		final double blink = 0.5 + 0.5 * Math.sin(System.currentTimeMillis() / 320.0);
		final Color wash = new Color(s.getRed(), s.getGreen(), s.getBlue(), (int) Math.round(60 + 40 * blink));
		final List<Rectangle> exempt = new ArrayList<>();

		// inventory tab: wash it, mark every non-exempt item, and note any exempt item carried
		Widget inv = client.getWidget(INVENTORY_GROUP, 0);
		if (inv != null && !inv.isHidden())
		{
			fill(g, wash, inv.getBounds());

			// match the spellbook X colour (orange while illegal); fall back to the shade if unavailable
			Color sym = plugin.spellbookStateColor();
			if (sym == null)
			{
				sym = s;
			}

			Widget[] items = inv.getDynamicChildren();
			if (items != null)
			{
				for (Widget item : items)
				{
					if (item == null || item.isHidden())
					{
						continue;
					}
					int id = item.getItemId();
					if (id <= 0)
					{
						continue;
					}
					if (plugin.isRestrictionExemptItem(id))
					{
						exempt.add(item.getBounds());
					}
					else
					{
						drawNoSymbol(g, item.getBounds(), sym);
					}
				}
			}
		}

		// worn-equipment tab: wash the whole panel and note the exempt item if it's worn
		Rectangle[] union = new Rectangle[1];
		Widget[] roots = client.getWidgetRoots();
		if (roots != null)
		{
			for (Widget root : roots)
			{
				scanEquip(root, 0, union, exempt);
			}
		}
		fill(g, wash, union[0]);

		// outlines drawn last, on top of the washes
		for (Rectangle b : exempt)
		{
			drawOutline(g, b, look.illegalExemptOutline());
		}
	}

	/** Accumulate the worn-equipment panel bounds (union) and any exempt worn-item slot bounds. */
	private void scanEquip(Widget w, int depth, Rectangle[] union, List<Rectangle> exempt)
	{
		if (w == null || depth > 8 || w.isHidden())
		{
			return;
		}
		if ((w.getId() >>> 16) == EQUIPMENT_GROUP)
		{
			Rectangle b = w.getBounds();
			if (b != null && b.width > 0 && b.height > 0)
			{
				union[0] = union[0] == null ? new Rectangle(b) : union[0].union(b);
				int id = w.getItemId();
				if (id > 0 && plugin.isRestrictionExemptItem(id))
				{
					exempt.add(b);
				}
			}
		}
		scanEquipChildren(w.getStaticChildren(), depth, union, exempt);
		scanEquipChildren(w.getDynamicChildren(), depth, union, exempt);
		scanEquipChildren(w.getNestedChildren(), depth, union, exempt);
	}

	private void scanEquipChildren(Widget[] children, int depth, Rectangle[] union, List<Rectangle> exempt)
	{
		if (children == null)
		{
			return;
		}
		for (Widget c : children)
		{
			scanEquip(c, depth + 1, union, exempt);
		}
	}

	private static void fill(Graphics2D g, Color c, Rectangle b)
	{
		if (b != null && b.width > 0 && b.height > 0)
		{
			g.setColor(c);
			g.fillRect(b.x, b.y, b.width, b.height);
		}
	}

	/** Bright outline (glow + solid) around an item's slot. */
	private void drawOutline(Graphics2D g, Rectangle b, Color base)
	{
		if (b == null || b.width <= 0)
		{
			return;
		}
		double blink = 0.5 + 0.5 * Math.sin(System.currentTimeMillis() / 260.0);
		int pad = 1;
		int x = b.x - pad;
		int y = b.y - pad;
		int w = b.width + pad * 2;
		int h = b.height + pad * 2;

		int glowA = (int) Math.round(60 + 110 * blink);
		g.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), glowA));
		g.setStroke(new BasicStroke(5f));
		g.drawRoundRect(x - 1, y - 1, w + 2, h + 2, 8, 8);

		g.setColor(new Color(0, 0, 0, 150));
		g.setStroke(new BasicStroke(3.5f));
		g.drawRoundRect(x, y, w, h, 6, 6);

		g.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), 255));
		g.setStroke(new BasicStroke(2f));
		g.drawRoundRect(x, y, w, h, 6, 6);
	}

	// ---------------------------------------------------------------- normal state

	private void renderNormal(Graphics2D g)
	{
		Widget inv = client.getWidget(INVENTORY_GROUP, 0);
		if (inv == null || inv.isHidden())
		{
			return;
		}
		Widget[] items = inv.getDynamicChildren();
		if (items == null)
		{
			return;
		}
		for (Widget item : items)
		{
			if (item == null || item.isHidden())
			{
				continue;
			}
			int id = item.getItemId();
			if (id <= 0)
			{
				continue;
			}
			Rectangle b = item.getBounds();
			if (b == null || b.width <= 0)
			{
				continue;
			}
			if (plugin.isDisabledFood(id))
			{
				drawStateCircle(g, b, look.overloadColor(), plugin.foodCircleFraction());
			}
			else if (plugin.isDisabledPotion(id))
			{
				drawStateCircle(g, b, look.depletedColor(), 1f);
			}
			else if (plugin.isOffLimitItem(id))
			{
				drawNoSymbol(g, b, new Color(230, 20, 20));
			}
		}
	}

	/**
	 * Colored circle + slash over a disabled item, sized/centred exactly like the gear marker. The outline
	 * glows and pulses in the given colour; while a timer is running (frac &lt; 1) the fill clears
	 * counter-clockwise to show the seconds passing.
	 */
	private void drawStateCircle(Graphics2D g, Rectangle b, Color base, float frac)
	{
		int d = Math.min(b.width, b.height) - 4;
		if (d < 6)
		{
			return;
		}
		int cx = b.x + b.width / 2;
		int cy = b.y + b.height / 2;
		int x = cx - d / 2;
		int y = cy - d / 2;
		float f = Math.max(0f, Math.min(1f, frac));
		double rr = d / 2.0;
		double off = rr * Math.cos(Math.toRadians(45));
		double blink = 0.5 + 0.5 * Math.sin(System.currentTimeMillis() / 320.0);

		// semi-transparent fill as a pie wedge: the empty part sweeps counter-clockwise as a timer runs down
		int startAngle = Math.round(90 + (1f - f) * 360f) % 360;
		int arcAngle = Math.round(f * 360f);
		g.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), 90));
		if (f >= 0.999f)
		{
			g.fillOval(x, y, d, d);
		}
		else if (arcAngle != 0)
		{
			g.fillArc(x, y, d, d, startAngle, arcAngle);
		}

		// pulsing glow halo, matching the alert text colour
		int glowA = Math.max(0, Math.min(255, (int) Math.round(45 + 95 * blink)));
		g.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), glowA));
		g.setStroke(new BasicStroke(5f));
		g.drawOval(x - 2, y - 2, d + 4, d + 4);
		g.setStroke(new BasicStroke(4f));
		g.drawOval(x - 1, y - 1, d + 2, d + 2);

		// dark backing slash for contrast
		g.setStroke(new BasicStroke(4f));
		g.setColor(new Color(0, 0, 0, 150));
		g.drawLine((int) (cx - off), (int) (cy - off), (int) (cx + off), (int) (cy + off));

		// opaque outline + diagonal slash
		g.setStroke(new BasicStroke(2.5f));
		g.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), 255));
		g.drawOval(x, y, d, d);
		g.drawLine((int) (cx - off), (int) (cy - off), (int) (cx + off), (int) (cy + off));
	}

	private void drawNoSymbol(Graphics2D g, Rectangle b, Color base)
	{
		if (b == null || b.width <= 0 || b.height <= 0)
		{
			return;
		}
		int d = Math.min(b.width, b.height) - 4;
		if (d < 6)
		{
			return;
		}
		int cx = b.x + b.width / 2;
		int cy = b.y + b.height / 2;
		int x = cx - d / 2;
		int y = cy - d / 2;
		double r = d / 2.0;
		double off = r * Math.cos(Math.toRadians(45));

		// translucent wash inside the circle
		g.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), 70));
		g.fillOval(x, y, d, d);

		// dark backing for contrast
		g.setStroke(new BasicStroke(4f));
		g.setColor(new Color(0, 0, 0, 170));
		g.drawOval(x, y, d, d);
		g.drawLine((int) (cx - off), (int) (cy - off), (int) (cx + off), (int) (cy + off));

		// circle + diagonal slash
		g.setStroke(new BasicStroke(2.5f));
		g.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), 240));
		g.drawOval(x, y, d, d);
		g.drawLine((int) (cx - off), (int) (cy - off), (int) (cx + off), (int) (cy + off));
	}
}

package com.battlemage;

