/**
 * The oath flow: a compact pop-up over the game view.
 *
 * <ul>
 *   <li>{@code GODS} - the four gods in quadrants, as on the plugin icon. Clicking a god
 *       highlights it; <b>Lock-in</b> commits, naming the doctrine rather than the god - you are
 *       choosing an alignment, and the god is who embodies it. Lock-in swears the oath.</li>
 *   <li>{@code TIP} - shown once ever, after the first Lock-in: a short note pointing at the side
 *       panel for the rulebook, the Wise Old Man for changing faction, and his BMM option. <b>Got it</b> closes the flow. Every later
 *       Lock-in closes the flow straight away. Either way the reveal callback fires on close.</li>
 * </ul>
 *
 * <p>Opened only by {@link WiseOldMan}, after the player rings the Cowbell amulet beside him and
 * chooses <i>Begin Battle-Mage Mode</i>. Nothing here is permanent - denounce from the side panel,
 * then return to him to choose again.
 */
@Singleton
public class OnboardingOverlay extends Overlay
{
	private static final int PAD = 14;
	private static final int CARD_W = 104;
	/** Crest, name, epithet - nothing more. */
	private static final int CARD_H = 82;
	/** The gap between the four quadrants, across and down. */
	private static final int QUAD_GAP = 10;
	private static final int BTN_H = 26;

	private static final Color SCRIM = new Color(6, 8, 11, 216);
	private static final Color PANEL = new Color(24, 27, 33, 250);
	private static final Color PANEL_LINE = new Color(70, 78, 90);
	private static final Color CARD = new Color(32, 36, 43);
	private static final Color EDGE = new Color(62, 69, 80);
	private static final Color INK = new Color(232, 236, 242);
	private static final Color INK_FAINT = new Color(104, 113, 126);

	private static final Font TITLE_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 19);
	private static final Font NAME_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 13);
	private static final Font BODY_FONT = new Font(Font.SANS_SERIF, Font.PLAIN, 11);
	private static final Font LABEL_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 9);
	private static final Font BTN_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 12);


	/** Stored beside the oath, so it never shows up as a setting. */
	private static final String KEY_TIP_SHOWN = "sidePanelTipShown";
	private static final String TIP_TITLE = "Your oath is sworn";
	private static final String[] TIP_COPY = {
		"Open the Battle-Mage Mode side panel to read the rulebook, which explains how this game mode works.",
		"",
		"To change factions, denounce yours in the side panel, then ring the Cowbell Amulet in front of the Wise Old Man again.",
		"",
		"Questions? Right-click the Wise Old Man and choose BMM.",
	};

	private enum Screen
	{
		GODS, TIP
	}

	private final Client client;
	private final Oath oath;
	private final Rules rules;
	private final MouseManager mouseManager;
	private final ConfigManager configManager;

	/** Fired when the flow finishes - the plugin starts the PKP bar's reveal. */
	private Runnable onComplete = () ->
	{
	};

	private Screen screen = Screen.GODS;
	private Faction selected;
	private boolean active;

	private final Map<Faction, Rectangle> factionHits = new LinkedHashMap<>();
	private Rectangle lockHit;
	private Rectangle gotItHit;

	private final MouseAdapter mouseAdapter = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent e)
		{
			if (!active || e.getButton() != MouseEvent.BUTTON1)
			{
				return e;
			}
			if (handleClick(e.getX(), e.getY()))
			{
				e.consume();
			}
			return e;
		}
	};

	@Inject
	private OnboardingOverlay(Client client, Oath oath, Rules rules, MouseManager mouseManager,
		ConfigManager configManager)
	{
		this.client = client;
		this.oath = oath;
		this.rules = rules;
		this.mouseManager = mouseManager;
		this.configManager = configManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(OverlayPriority.HIGHEST);
	}

	void setOnComplete(Runnable onComplete)
	{
		this.onComplete = onComplete == null ? () ->
		{
		} : onComplete;
	}

	/** Shows the oath flow from its first screen. */
	public void open()
	{
		if (active)
		{
			return;
		}
		active = true;
		screen = Screen.GODS;
		// Start on whatever god is already in force, so changing your mind is a one-click edit
		// rather than starting from a blank screen.
		Faction current = oath.getFaction();
		selected = current != null && current.isGod() ? current : null;
		mouseManager.registerMouseListener(mouseAdapter);
	}

	/** Whether the oath pop-up is on screen. */
	boolean isActive()
	{
		return active;
	}

	public void close()
	{
		if (!active)
		{
			return;
		}
		active = false;
		mouseManager.unregisterMouseListener(mouseAdapter);
	}

	// ------------------------------------------------------------------ input

	private boolean handleClick(int mx, int my)
	{
		if (screen == Screen.GODS)
		{
			for (Map.Entry<Faction, Rectangle> e : factionHits.entrySet())
			{
				if (e.getValue().contains(mx, my))
				{
					pickGod(e.getKey());
					return true;
				}
			}
			if (lockHit != null && lockHit.contains(mx, my) && selected != null)
			{
				lockIn();
				return true;
			}
			return false;
		}

		// TIP
		if (gotItHit != null && gotItHit.contains(mx, my))
		{
			configManager.setConfiguration(Oath.GROUP, KEY_TIP_SHOWN, true);
			finish();
		}
		// Swallow every click on this screen so it never reaches the game behind the pop-up.
		return true;
	}

	/** Closes the flow and starts the PKP bar's reveal. */
	private void finish()
	{
		close();
		onComplete.run();
	}

	private void pickGod(Faction f)
	{
		selected = f;
	}

	/** Swears to the highlighted god, then shows the one-time tip or closes the flow. */
	private void lockIn()
	{
		oath.swear(selected);
		Boolean shown = configManager.getConfiguration(Oath.GROUP, KEY_TIP_SHOWN, Boolean.class);
		if (shown == null || !shown)
		{
			screen = Screen.TIP;
			return;
		}
		finish();
	}

	// ----------------------------------------------------------------- render

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!active)
		{
			return null;
		}
		Rectangle view = viewportBounds();
		if (view == null || view.width < 80 || view.height < 80)
		{
			return null;
		}

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

		g.setColor(SCRIM);
		g.fillRect(view.x, view.y, view.width, view.height);

		clearHits();
		if (screen == Screen.GODS)
		{
			renderGods(g, view);
		}
		else
		{
			renderTextScreen(g, view);
		}
		return new Dimension(view.width, view.height);
	}

	private void clearHits()
	{
		factionHits.clear();
		lockHit = null;
		gotItHit = null;
	}

	/**
	 * The god screen.
	 *
	 * <p>The gods each hold a quadrant, matching the four sparkles around the cone on the plugin
	 * icon: Saradomin top left, Zamorak top right, Guthix bottom left, Zaros bottom right.
	 *
	 * <p>The panel is measured before it is drawn, walking the same arithmetic the draw pass walks,
	 * so the frame always closes below Lock-in rather than running off the bottom of the viewport.
	 */
	private void renderGods(Graphics2D g, Rectangle view)
	{
		int gridW = CARD_W * 2 + QUAD_GAP;
		int panelW = gridW + PAD * 2;
		int innerW = panelW - PAD * 2;

		int cardBlock = CARD_H;
		int gapBeforeButton = 6;

		int panelH = PAD
			+ 24                                  // title
			+ 6
			+ cardBlock                           // Saradomin and Zamorak
			+ QUAD_GAP + cardBlock                // Guthix and Zaros
			+ gapBeforeButton
			+ BTN_H                               // Lock in
			+ PAD;

		int px = view.x + (view.width - panelW) / 2;
		int py = view.y + Math.max(4, (view.height - panelH) / 2);
		drawPanel(g, px, py, panelW, panelH);

		int left = px + PAD;
		int right = left + CARD_W + QUAD_GAP;
		int y = py + PAD;

		g.setFont(TITLE_FONT);
		FontMetrics tfm = g.getFontMetrics();
		g.setColor(INK);
		g.drawString("Swear an oath", left + (innerW - tfm.stringWidth("Swear an oath")) / 2, y + 15);
		y += 24;

		y += 6;

		drawGodCard(g, Faction.SARADOMIN, left, y);
		drawGodCard(g, Faction.ZAMORAK, right, y);
		y += cardBlock + QUAD_GAP;

		drawGodCard(g, Faction.GUTHIX, left, y);
		drawGodCard(g, Faction.ZAROS, right, y);
		y += cardBlock;

		y += gapBeforeButton;

		lockHit = new Rectangle(left, y, innerW, BTN_H);
		boolean ready = selected != null;
		drawButton(g, lockHit,
			ready ? "Lock-in " + rules.lore(selected).epithet : "Choose Your Alignment",
			ready ? selected.getPrimary() : null, ready);
	}

	private void renderTextScreen(Graphics2D g, Rectangle view)
	{
		String title = TIP_TITLE;
		String[] copy = TIP_COPY;
		Faction f = oath.getFaction();
		Color accent = f != null ? f.getPrimary() : new Color(0x7FA8D8);

		// the same width as the god screen, so the two screens share one frame
		int panelW = CARD_W * 2 + QUAD_GAP + PAD * 2;
		int innerW = panelW - PAD * 2;

		// Drop lines off the end until the panel fits the viewport rather than letting the button
		// slide off the bottom of the screen where it can't be clicked.
		int chrome = PAD + 26 + 14 + BTN_H + PAD;
		int bodyBudget = Math.max(Briefing.LINE, view.height - 8 - chrome);
		String[] shown = copy;
		int bodyH = Briefing.height(g, shown, innerW);
		while (bodyH > bodyBudget && shown.length > 1)
		{
			shown = java.util.Arrays.copyOf(shown, shown.length - 1);
			bodyH = Briefing.height(g, shown, innerW);
		}
		int panelH = chrome + bodyH;

		int px = view.x + (view.width - panelW) / 2;
		int py = view.y + Math.max(4, (view.height - panelH) / 2);
		drawPanel(g, px, py, panelW, panelH);

		int left = px + PAD;
		int y = py + PAD;

		// Centred, matching the god screen, so both screens share one masthead.
		g.setFont(TITLE_FONT);
		FontMetrics tfm = g.getFontMetrics();
		g.setColor(INK);
		g.drawString(title, left + (innerW - tfm.stringWidth(title)) / 2, y + 15);
		y += 26;

		y = Briefing.draw(g, left, y, innerW, shown, accent);
		y += 14;

		gotItHit = new Rectangle(left, y, innerW, BTN_H);
		drawButton(g, gotItHit, "Got it", accent, true);
	}

	// ------------------------------------------------------------- pieces

	private void drawPanel(Graphics2D g, int px, int py, int w, int h)
	{
		g.setColor(PANEL);
		g.fill(new RoundRectangle2D.Double(px, py, w, h, 10, 10));
		g.setColor(PANEL_LINE);
		g.setStroke(new BasicStroke(1f));
		g.draw(new RoundRectangle2D.Double(px, py, w - 1, h - 1, 10, 10));
	}

	private void drawGodCard(Graphics2D g, Faction faction, int x, int y)
	{
		Rectangle card = new Rectangle(x, y, CARD_W, CARD_H);
		factionHits.put(faction, card);
		drawFactionCard(g, faction, card);
	}

	private void drawButton(Graphics2D g, Rectangle r, String label, Color fill, boolean enabled)
	{
		Color bg = fill != null ? fill : CARD;
		g.setColor(enabled ? bg : new Color(40, 44, 51));
		g.fill(new RoundRectangle2D.Double(r.x, r.y, r.width, r.height, 6, 6));
		g.setColor(enabled ? (fill != null ? fill : EDGE) : EDGE);
		g.setStroke(new BasicStroke(1f));
		g.draw(new RoundRectangle2D.Double(r.x + 1, r.y + 1, r.width - 2, r.height - 2, 6, 6));

		g.setFont(BTN_FONT);
		FontMetrics fm = g.getFontMetrics();
		g.setColor(!enabled ? INK_FAINT : (fill != null ? contrastOn(fill) : INK));
		g.drawString(label, r.x + (r.width - fm.stringWidth(label)) / 2, r.y + r.height / 2 + 5);
	}

	private void drawFactionCard(Graphics2D g, Faction faction, Rectangle r)
	{
		boolean isSelected = faction == selected;
		Color accent = faction.getPrimary();

		g.setColor(CARD);
		g.fill(new RoundRectangle2D.Double(r.x, r.y, r.width, r.height, 8, 8));
		if (isSelected)
		{
			g.setColor(FactionSigils.alpha(accent, 46));
			g.fill(new RoundRectangle2D.Double(r.x, r.y, r.width, r.height, 8, 8));
		}
		g.setColor(isSelected ? accent : EDGE);
		g.setStroke(new BasicStroke(isSelected ? 2f : 1f));
		g.draw(new RoundRectangle2D.Double(r.x + 1, r.y + 1, r.width - 2, r.height - 2, 8, 8));

		ContentPack.Lore lore = rules.lore(faction);

		FactionSigils.drawFaction(g, faction, r.x + (r.width - 38) / 2, r.y + 5, 38);

		g.setFont(NAME_FONT);
		FontMetrics fm = g.getFontMetrics();
		g.setColor(INK);
		centre(g, fm, lore.displayName, r, r.y + 58);

		// The one word of doctrine, and nothing else - the card is a choice, not a briefing.
		g.setFont(LABEL_FONT);
		fm = g.getFontMetrics();
		g.setColor(FactionSigils.alpha(accent, 235));
		centre(g, fm, lore.epithet.toUpperCase(), r, r.y + 72);
	}

	// ------------------------------------------------------------------ util

	/**
	 * The 3D game view, in canvas coordinates - the same resolution IllegalBehaviorOverlay uses, so
	 * both full-view overlays land in exactly the same place in fixed and resizable modes.
	 */
	private Rectangle viewportBounds()
	{
		int vx = client.getViewportXOffset();
		int vy = client.getViewportYOffset();
		int vw = client.getViewportWidth();
		int vh = client.getViewportHeight();
		if (vw <= 0 || vh <= 0)
		{
			vx = 0;
			vy = 0;
			vw = client.getCanvasWidth();
			vh = client.getCanvasHeight();
		}
		return (vw <= 0 || vh <= 0) ? null : new Rectangle(vx, vy, vw, vh);
	}

	private static void centre(Graphics2D g, FontMetrics fm, String text, Rectangle r, int baseline)
	{
		g.drawString(text, r.x + (r.width - fm.stringWidth(text)) / 2, baseline);
	}

	private static Color contrastOn(Color bg)
	{
		int luma = (int) (bg.getRed() * 0.299 + bg.getGreen() * 0.587 + bg.getBlue() * 0.114);
		return luma > 150 ? new Color(16, 18, 22) : Color.WHITE;
	}
}

package com.battlemage;

import java.awt.BasicStroke;
import java.awt.Composite;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.AffineTransform;
import java.awt.geom.GeneralPath;
import java.awt.geom.RoundRectangle2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The horizontal PKP bar. A normal movable overlay - drag it so it sits just above the chat box.
 */
class PkpBarOverlay extends Overlay
{
	private final BattleMagePlugin plugin;
	private final Appearance look;

	@Inject
	PkpBarOverlay(BattleMagePlugin plugin, Appearance look)
	{
		this.plugin = plugin;
		this.look = look;
		setPosition(OverlayPosition.BOTTOM_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setMovable(true);
		setSnappable(true);
	}

	/** How long the bar glints after the amulet catches a spill (matches the amulet's own glint). */
	private static final long SPARKLE_MS = 700L;

	/**
	 * When the Cowbell amulet catches a spill, a few of its glints show at that end of the bar too:
	 * more of them, and further in, the bigger the spill - up to a quarter of the bar.
	 */
	private void drawSpillSparkles(Graphics2D g, int w, int h)
	{
		long now = System.currentTimeMillis();
		long start = plugin.spillStartMs();
		int side = plugin.spillSide();
		long age = now - start;
		if (start == 0 || side == 0 || age < 0 || age >= SPARKLE_MS)
		{
			return;
		}
		double life = 1.0 - age / (double) SPARKLE_MS;
		double spill = Math.min(0.25, plugin.spillAmount());
		double reach = Math.max(6, w * spill);
		int count = 2 + (int) Math.round(spill / 0.25 * 6);
		Color c = side > 0 ? look.barColorFull() : look.barColorLow();
		java.util.Random r = new java.util.Random(start * 5 + 1);
		java.awt.Stroke old = g.getStroke();
		for (int k = 0; k < count; k++)
		{
			double in = reach * r.nextDouble();
			int cx = (int) Math.round(side > 0 ? w - 3 - in : 3 + in);
			int cy = 3 + r.nextInt(Math.max(1, h - 6));
			double beat = 0.5 + 0.5 * Math.sin(age / (60.0 + r.nextInt(50)) + r.nextDouble() * 6.28);
			double size = (1.5 + 2.5 * beat) * life;
			if (size < 1)
			{
				continue;
			}
			int a = clamp((int) Math.round(255 * life * (0.55 + 0.45 * beat)));
			int x0 = (int) Math.round(cx - size - 1);
			int x1 = (int) Math.round(cx + size + 1);
			int y0 = (int) Math.round(cy - size - 1);
			int y1 = (int) Math.round(cy + size + 1);
			// a dark edge first, so the star reads on its own colour of fill
			g.setStroke(new BasicStroke(3f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.setColor(new Color(0, 0, 0, clamp(a * 2 / 3)));
			g.drawLine(x0, cy, x1, cy);
			g.drawLine(cx, y0, cx, y1);
			// a coloured halo, then a white core
			g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), clamp(a / 2)));
			g.fillOval(cx - 3, cy - 3, 6, 6);
			g.setStroke(new BasicStroke(1.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.setColor(new Color(255, 255, 255, a));
			g.drawLine(x0, cy, x1, cy);
			g.drawLine(cx, y0, cx, y1);
			g.fillOval(cx - 1, cy - 1, 3, 3);
		}
		g.setStroke(old);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		// Hidden while banking (the bank covers the spot it usually sits in), except while the
		// appearance editor is open and the bar is being judged.
		if (!look.showBar() || (!look.isEditing() && plugin.bankOpen()))
		{
			return null;
		}

		plugin.noteBarBounds(getBounds());
		final int w = look.barWidth();
		final int h = look.barHeight();
		final int max = Math.max(1, plugin.getMaxPkp());
		final int cur = plugin.getCurrentPkp();
		// The appearance editor can ask for a sample fill (to judge the low/full colours) or a sample
		// overcharge; otherwise this is the real bar.
		final double sampleFill = look.sampleFill();
		final double frac = sampleFill >= 0 ? Math.min(1.0, sampleFill)
			: Math.max(0, Math.min(1.0, cur / (double) max));
		final boolean overcharged = look.sampleOvercharge() || (sampleFill < 0 && plugin.isOvercharged());

		// Hidden until the oath is sworn, then a one-time pop-in. Always shown while it is being edited.
		final double reveal = look.isEditing() ? 1.0 : plugin.revealProgress();
		if (reveal <= 0.0)
		{
			return null;
		}
		final AffineTransform savedTransform = g.getTransform();
		final Composite savedComposite = g.getComposite();
		RevealAnim.apply(g, reveal, w, h);

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		g.setColor(new Color(0, 0, 0, 200));
		g.fillRoundRect(0, 0, w, h, 8, 8);

		final int pad = 2;
		final int innerW = w - pad * 2;
		final int innerH = h - pad * 2;
		final int fillW = (int) Math.round(innerW * frac);
		g.setColor(overcharged ? look.overchargeColor()
			: lerp(look.barColorLow(), look.barColorFull(), frac));
		g.fillRoundRect(pad, pad, Math.max(0, fillW), innerH, 6, 6);

		if (look.showCostTicks())
		{
			g.setColor(new Color(255, 255, 255, 90));
			g.setStroke(new BasicStroke(1f));
			int cost = plugin.minSpellCost();
			if (cost > 0)
			{
				for (int v = cost; v < max; v += cost)
				{
					int x = pad + (int) Math.round(innerW * (v / (double) max));
					g.drawLine(x, pad, x, pad + innerH);
				}
			}
		}

		// regen shimmer: a glowing streak that sweeps across, brightest at the centre,
		// scaling speed + brightness with the regen rate and matching the border colour
		if (plugin.regenActive())
		{
			double intensity = plugin.regenIntensity();
			long period = (long) Math.max(280.0, 1000.0 / intensity);
			double p = (System.currentTimeMillis() % period) / (double) period; // 0..1 sweep
			double envelope = Math.sin(p * Math.PI);                            // 0 at ends, 1 at centre
			int peakAlpha = clamp((int) Math.round(130 * (0.45 + 0.55 * Math.min(1.0, intensity / 2.0))));
			int bandAlpha = clamp((int) Math.round(peakAlpha * envelope));
			if (bandAlpha > 0)
			{
				Color sc = plugin.barFrameColor();
				double bandX = pad + p * innerW;
				double sigma = Math.max(6.0, innerW / 14.0);
				int reach = (int) Math.round(sigma * 2.5);
				Shape oldClip = g.getClip();
				g.setClip(pad, pad, innerW, innerH);
				for (int dx = -reach; dx <= reach; dx++)
				{
					double falloff = Math.exp(-(dx * dx) / (2 * sigma * sigma));
					int a = clamp((int) Math.round(bandAlpha * falloff));
					if (a <= 0)
					{
						continue;
					}
					g.setColor(new Color(sc.getRed(), sc.getGreen(), sc.getBlue(), a));
					g.fillRect((int) Math.round(bandX) + dx, pad, 1, innerH);
				}
				g.setClip(oldClip);
			}
		}

		// poison water: green liquid sloshing inside the bar while poisoned/venomed, only across the
		// remaining PKP (the filled width). Its motion is paused via the plugin's freeze-aware clock
		// whenever the bar is frozen, and resumes on unfreeze.
		if (plugin.isPoisoned())
		{
			drawPoisonWater(g, pad, Math.max(0, fillW), innerH);
		}

		Color frame = plugin.barFrameColor();

		final double pulse = look.barPulse()
			? 0.6 + 0.4 * (0.5 + 0.5 * Math.sin(System.currentTimeMillis() / 320.0))
			: 1.0;
		final int glow = look.barGlow();
		final float thick = look.barBorderThickness();
		for (int i = glow; i >= 1; i--)
		{
			int a = clamp((int) Math.round(45.0 * pulse * (glow - i + 1) / glow));
			g.setColor(new Color(frame.getRed(), frame.getGreen(), frame.getBlue(), a));
			g.setStroke(new BasicStroke(thick + i * 2f));
			g.drawRoundRect(0, 0, w, h, 8, 8);
		}
		g.setColor(new Color(frame.getRed(), frame.getGreen(), frame.getBlue(),
			clamp((int) Math.round(frame.getAlpha() * pulse))));
		g.setStroke(new BasicStroke(thick));
		g.drawRoundRect(0, 0, w, h, 8, 8);

		drawEffectBorder(g, w, h, thick, pulse);

		double criticalLeft = plugin.criticalOverloadRemaining();
		if (criticalLeft > 0)
		{
			drawCriticalCountdown(g, w, h, pad, criticalLeft);
		}

		StringBuilder sb = new StringBuilder();
		String barText = look.barLabel();
		if (barText != null && !barText.isEmpty())
		{
			sb.append(barText);
		}
		if (look.showPkpValue())
		{
			if (sb.length() > 0)
			{
				sb.append("  ");
			}
			sb.append(cur).append(" / ").append(max);
		}
		if (plugin.isPkpFrozen())
		{
			if (sb.length() > 0)
			{
				sb.append("  ");
			}
			sb.append("FROZEN");
		}
		String label = sb.toString();
		Color labelColor = Color.WHITE;
		if (!label.isEmpty())
		{
			FontMetrics fm = g.getFontMetrics();
			int tx = (w - fm.stringWidth(label)) / 2;
			int ty = (h - fm.getHeight()) / 2 + fm.getAscent();
			g.setColor(Color.BLACK);
			g.drawString(label, tx + 1, ty + 1);
			g.setColor(labelColor);
			g.drawString(label, tx, ty);
		}

		if (look.barExhaust() && !look.isEditing())
		{
			drawSpillSparkles(g, w, h);
		}

		RevealAnim.restore(g, savedTransform, savedComposite);
		return new Dimension(w, h);
	}

	/**
	 * Overlays the active freeze / immunity effects on the bar's border. One effect paints a solid ring in
	 * its colour; several are interleaved as equal-length dashed segments (one pass per effect, each offset
	 * by one segment) that march around the border, so every running effect stays visible at once. The
	 * colours are the same ones the effect-timer chips use.
	 */
	private void drawEffectBorder(Graphics2D g, int w, int h, float thick, double pulse)
	{
		if (!look.effectBorderEnabled())
		{
			return;
		}
		// only effects that are actually locking the bar get a border segment; an armed-but-not-started
		// freeze shows on its timer badge alone, since it is not restricting the bar yet
		final java.util.List<BattleMagePlugin.ActiveEffect> fx = new java.util.ArrayList<>();
		for (BattleMagePlugin.ActiveEffect e : plugin.activeEffects())
		{
			if (!e.pending)
			{
				fx.add(e);
			}
		}
		if (fx.isEmpty())
		{
			return;
		}

		final int k = fx.size();
		final float ringThick = thick + 2f;
		final int alpha = clamp((int) Math.round(255 * pulse));

		if (k == 1)
		{
			Color c = fx.get(0).color;
			g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha));
			g.setStroke(new BasicStroke(ringThick));
			g.drawRoundRect(0, 0, w, h, 8, 8);
			return;
		}

		// segment length scales with the bar so short bars don't turn into a blur of dashes
		final float seg = Math.max(8f, (w + h) / (float) (6 * k));
		final float cycle = seg * k;
		final float march = (System.currentTimeMillis() % 2400L) / 2400f * cycle;

		for (int i = 0; i < k; i++)
		{
			Color c = fx.get(i).color;
			g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha));
			g.setStroke(new BasicStroke(ringThick, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 10f,
				new float[]{seg, seg * (k - 1)}, march + i * seg));
			g.drawRoundRect(0, 0, w, h, 8, 8);
		}
	}

	/**
	 * The CRITICAL OVERLOAD countdown, drawn as a bar inside the bar.
	 *
	 * <p>It lives on the bar because that is where the player is already looking. The lit span shrinks from the full width to nothing over the ten ticks, so a
	 * reset - any further attack refills it - reads as the bar snapping back to full.
	 *
	 * <p>It is drawn over the fill rather than beside it, in the critical colour, because the state
	 * it reports overrides everything the fill is saying at that moment.
	 */
	private void drawCriticalCountdown(Graphics2D g, int w, int h, int pad, double remaining)
	{
		final int innerW = w - pad * 2;
		final int lit = (int) Math.round(innerW * Math.max(0.0, Math.min(1.0, remaining)));
		final int band = Math.max(3, (h - pad * 2) / 4);
		final int y = h - pad - band;
		Color c = look.criticalColor();

		// the track, so the burned-through part stays legible against a full bar
		g.setColor(new Color(0, 0, 0, 150));
		g.fillRoundRect(pad, y, innerW, band, band, band);

		// a hard flash at the top of each tick makes a reset unmistakable
		int alpha = 200 + (int) Math.round(55 * Math.sin(System.currentTimeMillis() / 90.0));
		g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), clamp(alpha)));
		g.fillRoundRect(pad, y, Math.max(0, lit), band, band, band);
	}

	private void drawPoisonWater(Graphics2D g, int pad, int innerW, int innerH)
	{
		Shape oldClip = g.getClip();
		g.setClip(new RoundRectangle2D.Float(pad, pad, innerW, innerH, 6, 6));

		long t = plugin.poisonAnimTime();
		double phase = t / 240.0;
		double level = pad + innerH * 0.45;

		GeneralPath body = new GeneralPath();
		body.moveTo(pad - 2, pad + innerH + 2);
		for (int x = pad - 2; x <= pad + innerW + 2; x++)
		{
			body.lineTo(x, surfaceY(x, level, phase));
		}
		body.lineTo(pad + innerW + 2, pad + innerH + 2);
		body.closePath();
		g.setColor(new Color(60, 170, 70, 150));
		g.fill(body);

		GeneralPath surf = new GeneralPath();
		boolean first = true;
		for (int x = pad - 2; x <= pad + innerW + 2; x++)
		{
			double yy = surfaceY(x, level, phase);
			if (first)
			{
				surf.moveTo(x, yy);
				first = false;
			}
			else
			{
				surf.lineTo(x, yy);
			}
		}
		g.setColor(new Color(130, 235, 140, 200));
		g.setStroke(new BasicStroke(1.5f));
		g.draw(surf);

		g.setClip(oldClip);
	}

	private static double surfaceY(int x, double level, double phase)
	{
		return level + 2.0 * Math.sin(x * 0.18 + phase) + 1.0 * Math.sin(x * 0.09 - phase * 1.3);
	}

	private static Color lerp(Color a, Color b, double t)
	{
		int r = clamp((int) Math.round(a.getRed() + (b.getRed() - a.getRed()) * t));
		int g = clamp((int) Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t));
		int bl = clamp((int) Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t));
		int al = clamp((int) Math.round(a.getAlpha() + (b.getAlpha() - a.getAlpha()) * t));
		return new Color(r, g, bl, al);
	}

	private static int clamp(int v)
	{
		return Math.max(0, Math.min(255, v));
	}
}

package com.battlemage;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Floats +/- PKP change notifications upward just above the Report button box. Newer changes appear at the
 * bottom and push older ones up; each fades over the configured duration.
 */
class PkpPopupOverlay extends Overlay
{
	/** A state that was stopped ("OVERLOAD AVERTED") is set a size smaller than the PKP numbers. */
	private static final Font LABEL_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 13);

	private final Client client;
	private final BattleMagePlugin plugin;
	private final Appearance look;
	private final Rules rules;

	@Inject
	PkpPopupOverlay(Client client, BattleMagePlugin plugin, Appearance look, Rules rules)
	{
		this.client = client;
		this.plugin = plugin;
		this.look = look;
		this.rules = rules;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!look.pkpPopupsEnabled())
		{
			return null;
		}
		List<BattleMagePlugin.PkpPopup> popups = plugin.pkpPopups();
		if (popups.isEmpty())
		{
			return null;
		}
		Widget w = client.getWidget(rules.reportWidgetGroup(), rules.reportWidgetChild());
		if (w == null || w.isHidden())
		{
			return null;
		}
		Rectangle b = w.getBounds();
		if (b == null || b.width <= 0)
		{
			return null;
		}

		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 16));
		final FontMetrics fm = g.getFontMetrics();
		final int cx = b.x + b.width / 2;
		final int baseY = b.y - 6;
		final long now = System.currentTimeMillis();
		final long life = Math.max(1, look.pkpPopupSeconds()) * 1000L;
		final int n = popups.size();

		for (int i = 0; i < n; i++)
		{
			BattleMagePlugin.PkpPopup p = popups.get(i);
			double age = (now - p.spawnMs) / (double) life;
			if (age < 0 || age >= 1.0)
			{
				continue;
			}
			int slot = n - 1 - i;                 // newest at the bottom, older pushed up
			int rise = (int) Math.round(age * 12); // gentle upward drift as it fades
			int y = baseY - slot * 18 - rise;
			int alpha = Math.max(0, Math.min(255, (int) Math.round(255 * (1.0 - age))));
			if (p.label != null)
			{
				// a state that something stopped: words in that state's colour, a size smaller so a
				// long label still fits the column, with a stronger outline to read over the game
				Font old = g.getFont();
				g.setFont(LABEL_FONT);
				FontMetrics lfm = g.getFontMetrics();
				int lx = cx - lfm.stringWidth(p.label) / 2;
				Color lc = p.color;
				g.setColor(new Color(0, 0, 0, (int) (alpha * 0.85)));
				g.drawString(p.label, lx + 1, y + 1);
				g.drawString(p.label, lx - 1, y + 1);
				g.setColor(new Color(lc.getRed(), lc.getGreen(), lc.getBlue(), alpha));
				g.drawString(p.label, lx, y);
				g.setFont(old);
				continue;
			}
			String text = plugin.fmtPkpDelta(p.delta);
			int tx = cx - fm.stringWidth(text) / 2;

			// loss is always red; gain is cyan like overcharge. When poisoned, both shift toward a sickly
			// green to show poison is affecting PKP gain/loss. Deliberately independent of the bar glow colour.
			Color col = p.delta >= 0 ? look.overchargeColor() : new Color(0xFF2A2A);
			if (plugin.isPoisoned())
			{
				col = blend(col, new Color(80, 200, 85), 0.55f);
			}

			g.setColor(new Color(0, 0, 0, (int) (alpha * 0.7)));
			g.drawString(text, tx + 1, y + 1);
			g.setColor(new Color(col.getRed(), col.getGreen(), col.getBlue(), alpha));
			g.drawString(text, tx, y);
		}
		return null;
	}

	private static Color blend(Color a, Color b, float f)
	{
		float g = 1f - f;
		int r = Math.round(a.getRed() * g + b.getRed() * f);
		int gr = Math.round(a.getGreen() * g + b.getGreen() * f);
		int bl = Math.round(a.getBlue() * g + b.getBlue() * f);
		return new Color(Math.min(255, r), Math.min(255, gr), Math.min(255, bl));
	}
}

package com.battlemage;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Full-canvas punishment overlay. While PKP is depleted it stays on screen (grey wash + PKP DEPLETED)
 * until you melee back to full; while overloaded it shows PKP OVERLOAD until you cast. Both pulse gently.
 */
class PkpStateOverlay extends Overlay
{
	private final Client client;
	private final BattleMagePlugin plugin;
	private final Appearance look;

	@Inject
	PkpStateOverlay(Client client, BattleMagePlugin plugin, Appearance look)
	{
		this.client = client;
		this.plugin = plugin;
		this.look = look;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		// The appearance editor can ask for a sample state, so its settings can be judged on screen.
		final Appearance.Sample sample = look.sample();
		final boolean previewing = sample != Appearance.Sample.NONE;

		// the ILLEGAL warning takes over the screen (hazard tape + orange inventory); don't also show
		// the PSI OVERLOAD / PSI DEPLETED titles or wash underneath it.
		if (!previewing && plugin.illegalBehaviorActive())
		{
			return null;
		}

		final boolean critical = previewing ? sample == Appearance.Sample.CRITICAL : plugin.criticalOverloadActive();
		final boolean depleted = previewing ? sample == Appearance.Sample.DEPLETED : !critical && plugin.isDepleted();
		final boolean overloaded = previewing ? sample == Appearance.Sample.OVERLOAD
			: !critical && !depleted && plugin.isOverloaded();
		if (!critical && !depleted && !overloaded)
		{
			look.setStateTextBounds(null);
			return null;
		}

		final int cw = client.getCanvasWidth();
		final int ch = client.getCanvasHeight();
		if (cw <= 0 || ch <= 0)
		{
			return null;
		}

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		// gentle continuous pulse (0..1)
		double blink = 0.5 + 0.5 * Math.sin(System.currentTimeMillis() / 320.0);
		// the exact curve the PKP bar's frame uses, so the state text breathes in lockstep with the bar
		double pulse = look.barPulse() ? 0.6 + 0.4 * blink : 1.0;

		if (depleted && look.desaturateScreen())
		{
			int a = clamp((int) Math.round(look.desaturationStrength() * (0.7 + 0.3 * blink)));
			g.setColor(new Color(128, 128, 128, a));
			g.fillRect(0, 0, cw, ch);
		}
		else if (overloaded)
		{
			Color o = look.overloadColor();
			int a = clamp((int) Math.round(70 * (0.7 + 0.3 * blink)));
			g.setColor(new Color(o.getRed() / 3, 0, o.getBlue() / 3, a));
			g.fillRect(0, 0, cw, ch);
		}
		else if (critical)
		{
			// CRITICAL OVERLOAD keeps the centre of the screen clear - no hazard tape - so the yellow
			// reads as a wash at exactly the opacity the overload and depletion states use.
			Color c = look.criticalColor();
			int a = clamp((int) Math.round(70 * (0.7 + 0.3 * blink)));
			g.setColor(new Color(c.getRed() / 2, c.getGreen() / 3, 0, a));
			g.fillRect(0, 0, cw, ch);
		}

		String text = critical ? look.criticalText()
			: (depleted ? look.depletedText() : look.overloadText());
		text = text == null ? "" : text;
		if (text.isEmpty())
		{
			look.setStateTextBounds(null);
			return null;
		}
		Color base = critical ? look.criticalColor()
			: (depleted ? look.depletedColor() : look.overloadColor());

		int baseSize = critical ? Math.max(20, ch / 15) : Math.max(28, ch / 9);
		int scale = critical ? look.criticalTextScalePercent()
			: (depleted ? look.depletedTextScalePercent() : look.overloadTextScalePercent());
		int size = (int) Math.round(baseSize * (scale / 100.0));
		// the text itself pulses (like the bar frame) instead of being wrapped in a soft halo, so it
		// stays fully saturated at its brightest and never washes out against a busy scene
		int textAlpha = clamp((int) Math.round(255 * pulse));

		g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, size));
		FontMetrics fm = g.getFontMetrics();

		// Each text sits wherever the player dragged it in the appearance editor (CRITICAL has its own
		// spot; depleted and overload share one). Until it is moved by hand it sits centred above the
		// PKP bar with its bottom ANCHOR_GAP_PX above the bar's top edge. With the bar hidden it falls
		// back to the middle of the screen.
		final double xp = critical ? look.criticalTextXPercent() : look.stateTextXPercent();
		final double yp = critical ? look.criticalTextYPercent() : look.stateTextYPercent();
		int tx;
		int ty;
		java.awt.Rectangle bar = plugin.pkpBarBounds();
		if ((xp < 0 || yp < 0) && look.showBar() && bar.width > 0 && bar.height > 0)
		{
			ty = bar.y - Appearance.ANCHOR_GAP_PX - fm.getDescent();
			tx = (int) Math.round(bar.getCenterX()) - fm.stringWidth(text) / 2;
		}
		else
		{
			int cx = (int) Math.round(cw * ((xp < 0 ? 50 : xp) / 100.0));
			int cy = (int) Math.round(ch * ((yp < 0 ? 50 : yp) / 100.0));
			ty = cy + fm.getAscent() / 2;
			tx = cx - fm.stringWidth(text) / 2;
		}

		// Build the glyph outline once: stroking it gives a clean, gap-free black edge at any font
		// size, which reads far better over the 3D scene than the old offset-drawString halo.
		Shape glyphs = g.getFont()
			.createGlyphVector(g.getFontRenderContext(), text)
			.getOutline(tx, ty);

		// hard drop shadow for depth
		Graphics2D sh = (Graphics2D) g.create();
		try
		{
			sh.translate(Math.max(3, size / 22), Math.max(3, size / 22));
			sh.setColor(new Color(0, 0, 0, 210));
			sh.fill(glyphs);
		}
		finally
		{
			sh.dispose();
		}

		// solid black outline, thickness scaled to the font
		g.setColor(new Color(0, 0, 0, 240));
		g.setStroke(new BasicStroke(Math.max(3f, size / 16f),
			BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.draw(glyphs);

		// pulsing fill
		g.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), textAlpha));
		g.fill(glyphs);

		// Remember where the text is, so the appearance editor can drag it. While previewing a
		// movable state, a dashed box and a hint show that it can be picked up.
		java.awt.Rectangle bounds = glyphs.getBounds();
		bounds.grow(8, 8);
		look.setStateTextBounds(bounds);
		if (previewing)
		{
			g.setColor(new Color(255, 255, 255, 170));
			g.setStroke(new BasicStroke(1.5f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 10f,
				new float[]{6f, 5f}, 0f));
			g.draw(bounds);
			g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));
			String hint = "Drag to move";
			int hw = g.getFontMetrics().stringWidth(hint);
			g.setColor(new Color(0, 0, 0, 200));
			g.drawString(hint, bounds.x + (bounds.width - hw) / 2 + 1, bounds.y + bounds.height + 15);
			g.setColor(Color.WHITE);
			g.drawString(hint, bounds.x + (bounds.width - hw) / 2, bounds.y + bounds.height + 14);
		}

		return null;
	}

	private static int clamp(int v)
	{
		return Math.max(0, Math.min(255, v));
	}
}

package com.battlemage;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.MenuEntry;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * Pushes PKP tooltips: item effects when hovering the inventory / worn-equipment, and per-mode spell
 * costs when hovering a PK spell in the spellbook or autocast-selection menu.
 */
class PkpTooltipOverlay extends Overlay
{
	private static final int INVENTORY_GROUP = 149;
	private static final int EQUIPMENT_TAB_GROUP = 387;
	private static final int BANK_GROUP = 12;
	private static final int BANK_INVENTORY_GROUP = 15;

	private final Client client;
	private final BattleMagePlugin plugin;
	private final Appearance look;
	private final TooltipManager tooltipManager;

	@Inject
	PkpTooltipOverlay(Client client, BattleMagePlugin plugin, Appearance look, TooltipManager tooltipManager)
	{
		this.client = client;
		this.plugin = plugin;
		this.look = look;
		this.tooltipManager = tooltipManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{

		MenuEntry[] menu = client.getMenuEntries();
		if (menu.length == 0)
		{
			return null;
		}

		// item tooltips (inventory / worn equipment). The equip option is stripped from blocked
		//    items, so the item-bearing entry may not be on top - scan all entries for it.
		if (look.inventoryTooltips())
		{
			int itemId = -1;
			for (int i = menu.length - 1; i >= 0; i--)
			{
				Widget mw = menu[i].getWidget();
				if (mw == null)
				{
					continue;
				}
				int group = mw.getId() >>> 16;
				if (group != INVENTORY_GROUP && group != EQUIPMENT_TAB_GROUP
					&& group != BANK_GROUP && group != BANK_INVENTORY_GROUP)
				{
					continue;
				}
				int id = menu[i].getItemId();
				if (id <= 0)
				{
					id = mw.getItemId();
				}
				if (id > 0)
				{
					itemId = id;
					break;
				}
			}
			if (itemId > 0)
			{
				String text = plugin.tooltipFor(itemId);
				if (text != null)
				{
					tooltipManager.add(new Tooltip(text));
				}
				return null;
			}
		}

		// spellbook hover text is deliberately not shown - spells carry no plugin-side name or cost label
		return null;
	}

}

package com.battlemage;

import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * The three groups an action can fall into for PKP purposes. These are cost buckets only - they carry no
 * display name, because cast cards are labelled with the spell's own spellbook name.
 *
 * <p>{@link #SPELLS} is the single source of truth for spell recognition: every combat spell in every
 * spellbook appears there once. (Each entry still carries its old Magic-level tier schedule, but costs
 * no longer change with level: every spell in a family costs the same.) Membership of {@link #CURSE} is not decided here at all - it comes from the editable
 * curse-spell list in the config, so the group can be re-scoped without touching the code.</p>
 */
public enum PsiAction
{
	/** Any melee attack. Restores PKP. */
	MELEE,
	/** Any spell that damages an opponent, in any spellbook. */
	COMBAT,
	/** Spells that target an opponent but only debuff or root it. */
	CURSE;

	// ---------------------------------------------------------------- per-spell metadata

	/**
	 * Cost-tier schedule for one spell. {@code thresholds} are ascending Magic levels and {@code tiers} the
	 * cost tier (0 = newest/base, 1 = first reduction, 2 = second reduction) that applies at and above each.
	 */
	public static final class SpellMeta
	{
		private final int[] thresholds;
		private final int[] tiers;

		SpellMeta(int[] thresholds, int[] tiers)
		{
			this.thresholds = thresholds;
			this.tiers = tiers;
		}

		/** Cost tier (0/1/2) at the given Magic level. */
		public int tierAt(int level)
		{
			int t = 0;
			for (int i = 0; i < thresholds.length; i++)
			{
				if (level >= thresholds[i])
				{
					t = tiers[i];
				}
			}
			return t;
		}
	}

	/** Tier ladders: a 5-spell elemental line steps down twice, the top spell of a line only once. */
	private static final int[] STEP = {0, 1, 2};
	private static final int[] STEP2 = {0, 1};
	private static final int[] FLAT = new int[0];

	private static final Map<String, SpellMeta> SPELLS = buildSpells();

	private static Map<String, SpellMeta> buildSpells()
	{
		Map<String, SpellMeta> m = new HashMap<>();

		// ---- standard: wind line
		put(m, "Wind Strike", new int[]{1, 17, 41}, STEP);
		put(m, "Wind Bolt", new int[]{17, 41, 62}, STEP);
		put(m, "Wind Blast", new int[]{41, 62, 81}, STEP);
		put(m, "Wind Wave", new int[]{62, 81, 99}, STEP);
		put(m, "Wind Surge", new int[]{81, 99}, STEP2);

		// ---- standard: water line
		put(m, "Water Strike", new int[]{5, 23, 47}, STEP);
		put(m, "Water Bolt", new int[]{23, 47, 65}, STEP);
		put(m, "Water Blast", new int[]{47, 65, 85}, STEP);
		put(m, "Water Wave", new int[]{65, 85, 99}, STEP);
		put(m, "Water Surge", new int[]{85, 99}, STEP2);

		// ---- standard: earth line
		put(m, "Earth Strike", new int[]{9, 29, 53}, STEP);
		put(m, "Earth Bolt", new int[]{29, 53, 70}, STEP);
		put(m, "Earth Blast", new int[]{53, 70, 90}, STEP);
		put(m, "Earth Wave", new int[]{70, 90, 99}, STEP);
		put(m, "Earth Surge", new int[]{90, 99}, STEP2);

		// ---- standard: fire line
		put(m, "Fire Strike", new int[]{13, 35, 59}, STEP);
		put(m, "Fire Bolt", new int[]{35, 59, 75}, STEP);
		put(m, "Fire Blast", new int[]{59, 75, 95}, STEP);
		put(m, "Fire Wave", new int[]{75, 95, 99}, STEP);
		put(m, "Fire Surge", new int[]{95, 99}, STEP2);

		// ---- standard: god spells + one-offs
		put(m, "Crumble Undead", FLAT, FLAT);
		put(m, "Iban Blast", FLAT, FLAT);
		put(m, "Magic Dart", FLAT, FLAT);
		put(m, "Slayer Dart", FLAT, FLAT);
		put(m, "Saradomin Strike", FLAT, FLAT);
		put(m, "Claws of Guthix", FLAT, FLAT);
		put(m, "Flames of Zamorak", FLAT, FLAT);
		put(m, "Charge", FLAT, FLAT);

		// ---- ancient: smoke line
		put(m, "Smoke Rush", new int[]{50, 62, 74}, STEP);
		put(m, "Smoke Burst", new int[]{62, 74, 86}, STEP);
		put(m, "Smoke Blitz", new int[]{74, 86, 99}, STEP);
		put(m, "Smoke Barrage", new int[]{86, 99}, STEP2);

		// ---- ancient: shadow line
		put(m, "Shadow Rush", new int[]{52, 64, 76}, STEP);
		put(m, "Shadow Burst", new int[]{64, 76, 88}, STEP);
		put(m, "Shadow Blitz", new int[]{76, 88, 99}, STEP);
		put(m, "Shadow Barrage", new int[]{88, 99}, STEP2);

		// ---- ancient: blood line
		put(m, "Blood Rush", new int[]{56, 68, 80}, STEP);
		put(m, "Blood Burst", new int[]{68, 80, 92}, STEP);
		put(m, "Blood Blitz", new int[]{80, 92, 99}, STEP);
		put(m, "Blood Barrage", new int[]{92, 99}, STEP2);

		// ---- ancient: ice line
		put(m, "Ice Rush", new int[]{58, 70, 82}, STEP);
		put(m, "Ice Burst", new int[]{70, 82, 94}, STEP);
		put(m, "Ice Blitz", new int[]{82, 94, 99}, STEP);
		put(m, "Ice Barrage", new int[]{94, 99}, STEP2);

		// ---- arceuus: grasps + demonbanes
		put(m, "Ghostly Grasp", new int[]{35, 55, 79}, STEP);
		put(m, "Skeletal Grasp", new int[]{56, 79}, STEP2);
		put(m, "Undead Grasp", FLAT, FLAT);
		put(m, "Inferior Demonbane", new int[]{44, 62, 82}, STEP);
		put(m, "Superior Demonbane", new int[]{62, 82}, STEP2);
		put(m, "Dark Demonbane", FLAT, FLAT);

		// ---- debuff / root spells. Registered so they are recognised as combat spells; the curse-spell
		// list in the config decides which of them are charged the curse cost instead of the combat cost.
		put(m, "Confuse", FLAT, FLAT);
		put(m, "Weaken", FLAT, FLAT);
		put(m, "Curse", FLAT, FLAT);
		put(m, "Vulnerability", FLAT, FLAT);
		put(m, "Enfeeble", FLAT, FLAT);
		put(m, "Stun", FLAT, FLAT);
		put(m, "Bind", FLAT, FLAT);
		put(m, "Snare", FLAT, FLAT);
		put(m, "Entangle", FLAT, FLAT);
		put(m, "Teleport Block", FLAT, FLAT);
		put(m, "Tele Block", FLAT, FLAT);

		return Collections.unmodifiableMap(m);
	}

	private static void put(Map<String, SpellMeta> m, String name, int[] th, int[] ti)
	{
		m.put(name.toLowerCase(Locale.ROOT), new SpellMeta(th, ti));
	}

	public static SpellMeta spellMeta(String name)
	{
		return name == null ? null : SPELLS.get(name.toLowerCase(Locale.ROOT).trim());
	}

	// ---------------------------------------------------------------- combat-spell recognition

	/** Every spell in the table is a combat spell except the self-cast Charge buff. */
	public static boolean isKnownCombatSpell(String name)
	{
		return spellMeta(name) != null && !"charge".equals(name.toLowerCase(Locale.ROOT).trim());
	}
}

package com.battlemage;

import java.awt.AlphaComposite;
import java.awt.Composite;
import java.awt.Graphics2D;
import java.awt.geom.AffineTransform;

/**
 * The one-time pop-in the PKP bar plays when a player finishes the oath.
 *
 * <p>Both overlays draw from their own origin, so the whole effect is a scale about the centre of
 * their box plus a fade. {@link #apply} stashes nothing - the caller saves the transform and
 * composite and hands them back to {@link #restore}, which keeps this usable on the shared
 * {@code Graphics2D} an overlay is given without creating and disposing a copy each frame.
 */
final class RevealAnim
{
	/** How long the pop-in runs. Long enough to read as deliberate, short enough not to annoy. */
	static final long DURATION_MS = 700L;

	private RevealAnim()
	{
	}

	/**
	 * Scales about the box's centre and fades in.
	 *
	 * @param progress 0 at the start, 1 when finished; values &gt;= 1 are a no-op
	 */
	static void apply(Graphics2D g, double progress, int w, int h)
	{
		if (progress >= 1.0)
		{
			return;
		}
		double t = Math.max(0.0, progress);
		// A small overshoot past full size, so it lands rather than merely stopping.
		double scale = 0.55 + 0.45 * easeOutBack(t);
		float alpha = (float) Math.max(0.0, Math.min(1.0, t * 1.7));

		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
		g.translate(w / 2.0, h / 2.0);
		g.scale(scale, scale);
		g.translate(-w / 2.0, -h / 2.0);
	}

	static void restore(Graphics2D g, AffineTransform savedTransform, Composite savedComposite)
	{
		g.setTransform(savedTransform);
		g.setComposite(savedComposite);
	}

	/** Overshoots ~10% then settles. */
	private static double easeOutBack(double t)
	{
		double c1 = 1.70158;
		double c3 = c1 + 1.0;
		double p = t - 1.0;
		return 1.0 + c3 * p * p * p + c1 * p * p;
	}
}

package com.battlemage;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * The plugin's view of the bundled content pack, resolved for whichever god is in force.
 *
 * <p>Every method here replaces a setting that used to sit in {@link BattleMageConfig}, keeping the
 * old name and return type so call sites read the same as before. List-shaped values are joined
 * back into the comma-separated strings the plugin's existing parsers expect, which keeps all the
 * parsing and caching in {@code BattleMagePlugin} untouched.
 *
 * <p>With no god chosen - before the oath screen is finished - the pack is not consulted at all
 * and every rule returns its inert value, so nothing is restricted and no PKP is spent.
 */
@Slf4j
@Singleton
public class Rules
{
	private static final String RESOURCE = "/battlemage-codex.json";

	/** One game tick, in milliseconds. The client's own clock, and the unit the pack authors in. */
	private static final double TICK_MS = 600.0;

	private final Oath oath;
	private final Gson gson;

	private ContentPack pack;
	private ContentPack.Profile active;
	private boolean loadFailed;

	@Inject
	public Rules(Oath oath, Gson gson)
	{
		this.oath = oath;
		this.gson = gson;
		loadPack();
		refresh();
	}

	// ------------------------------------------------------------------ loading

	private void loadPack()
	{
		try (InputStream in = Rules.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				loadFailed = true;
				log.error("Content pack {} is missing from the jar; all rules are inert.", RESOURCE);
				pack = new ContentPack();
				return;
			}
			pack = gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), ContentPack.class);
			if (pack == null)
			{
				throw new IOException("empty pack");
			}
			log.debug("Loaded content pack v{} ({} profiles)", pack.formatVersion, pack.profiles.size());
		}
		catch (Exception e)
		{
			loadFailed = true;
			pack = new ContentPack();
			log.error("Could not read the content pack; all rules are inert.", e);
		}
	}

	/** Re-resolves the active ruleset. Call after the god changes. */
	public void refresh()
	{
		String key = oath.getRulesetKey();
		active = key == null ? null : pack.profile(key);
		if (key != null && active == null)
		{
			log.warn("Content pack has no ruleset for {}; rules are inert until it is added.", key);
		}
	}

	/** True when a god is chosen and the pack actually has rules for it. */
	public boolean isActive()
	{
		return active != null;
	}

	public boolean isPackMissing()
	{
		return loadFailed;
	}

	/**
	 * Any faction's pack entry, not just the active one - the oath screen needs to describe gods the
	 * player has not sworn to yet. Null when the pack has no entry for it.
	 */
	public ContentPack.Profile packEntry(Faction faction)
	{
		return faction == null ? null : pack.profile(faction.name());
	}

	/**
	 * The authored words for a god, never null. Missing fields are filled from {@link Faction} so
	 * the oath screen reads correctly against a pack whose lore has not been written yet.
	 */
	public ContentPack.Lore lore(Faction faction)
	{
		ContentPack.Lore out = new ContentPack.Lore();
		if (faction == null)
		{
			return out;
		}
		ContentPack.Profile p = packEntry(faction);
		ContentPack.Lore src = p == null ? null : p.lore;

		out.displayName = pick(src == null ? null : src.displayName, faction.getDisplayName());
		out.epithet = pick(src == null ? null : src.epithet, faction.getEpithet());
		return out;
	}

	private static String pick(String authored, String fallback)
	{
		return authored == null || authored.trim().isEmpty() ? fallback : authored.trim();
	}

	// ------------------------------------------------------------------ joining

	private static String join(List<String> values)
	{
		if (values == null || values.isEmpty())
		{
			return "";
		}
		return String.join(",", values);
	}

	private static String joinIds(List<Integer> values)
	{
		if (values == null || values.isEmpty())
		{
			return "";
		}
		StringBuilder sb = new StringBuilder();
		for (Integer v : values)
		{
			if (v == null)
			{
				continue;
			}
			if (sb.length() > 0)
			{
				sb.append(',');
			}
			sb.append(v.intValue());
		}
		return sb.toString();
	}

	private static String joinPairs(Map<String, Integer> values)
	{
		if (values == null || values.isEmpty())
		{
			return "";
		}
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<String, Integer> e : values.entrySet())
		{
			if (e.getKey() == null || e.getValue() == null)
			{
				continue;
			}
			if (sb.length() > 0)
			{
				sb.append(',');
			}
			sb.append(e.getKey()).append(':').append(e.getValue().intValue());
		}
		return sb.toString();
	}

	private static String joinEffects(List<ContentPack.Effect> values)
	{
		if (values == null || values.isEmpty())
		{
			return "";
		}
		StringBuilder sb = new StringBuilder();
		for (ContentPack.Effect e : values)
		{
			if (e == null || e.name == null || e.name.trim().isEmpty())
			{
				continue;
			}
			if (sb.length() > 0)
			{
				sb.append(',');
			}
			sb.append(e.name).append(':').append(e.delta);
			if (e.effects != null && !e.effects.isEmpty())
			{
				sb.append(':').append(String.join("+", e.effects));
			}
		}
		return sb.toString();
	}

	// ------------------------------------------------------- shared: magic gate

	private ContentPack.Gate gate()
	{
		return pack.shared == null ? new ContentPack.Gate() : pack.shared.gate;
	}

	private ContentPack.Anims anims()
	{
		return pack.shared == null ? new ContentPack.Anims() : pack.shared.anims;
	}

	private ContentPack.Lockdown lockdown()
	{
		return pack.shared == null ? new ContentPack.Lockdown() : pack.shared.lockdown;
	}

	private ContentPack.Varps varps()
	{
		return pack.shared == null ? new ContentPack.Varps() : pack.shared.varps;
	}

	private ContentPack.Cannon cannon()
	{
		return pack.shared == null || pack.shared.cannon == null
			? new ContentPack.Cannon() : pack.shared.cannon;
	}

	/**
	 * The magic-attack gate is identical for every god, by design. It is still gated on a god having
	 * been chosen, so the plugin stays inert before the oath.
	 */
	public boolean enforceMagicAttack()
	{
		return isActive() && gate().enforceMagicAttack;
	}

	public int magicAttackMinimum()
	{
		return gate().magicAttackMinimum;
	}

	public int magicAttackThreshold()
	{
		return gate().magicAttackThreshold;
	}

	// ------------------------------------------------------ shared: animations

	public String meleeAnimationIds()
	{
		return joinIds(anims().meleeAnimationIds);
	}

	public String rangedAnimationIds()
	{
		return joinIds(anims().rangedAnimationIds);
	}

	public String targetCastAnimationIds()
	{
		return joinIds(anims().targetCastAnimationIds);
	}

	public String curseCastAnimationIds()
	{
		return joinIds(anims().curseCastAnimationIds);
	}

	public String selfCastAnimationIds()
	{
		return joinIds(anims().selfCastAnimationIds);
	}

	public String sitAnimationIds()
	{
		return joinIds(anims().sitAnimationIds);
	}

	public String blockAnimationIds()
	{
		return joinIds(anims().blockAnimationIds);
	}

	// -------------------------------------------------------- shared: lockdown

	/** Menu options treated as teleports and stripped during CRITICAL OVERLOAD. */
	public String teleportActions()
	{
		return join(lockdown().teleportActions);
	}

	// -------------------------------------------------------- shared: the cannon

	/**
	 * Whether the Dwarf multicannon window is being enforced.
	 *
	 * <p>Gated the same way the magic gate is: a restriction belongs to the faction system, so it is
	 * inert before an oath is sworn.
	 */
	public boolean enforceCannonLevel()
	{
		return isActive() && oath.getFaction() != Faction.FACTIONLESS && cannon().enforceCannonLevel;
	}

	/** The first Ranged level at which a cannon may no longer be placed. */
	public int cannonMaxRangedLevel()
	{
		return cannon().maxRangedLevel;
	}

	/** The menu options that place a cannon, as a comma-separated list. */
	public String cannonSetupActions()
	{
		return join(cannon().setupActions);
	}

	/** The substring that identifies a cannon piece by name. */
	public String cannonItemKeyword()
	{
		String k = cannon().cannonItemKeyword;
		return k == null ? "" : k.trim().toLowerCase(java.util.Locale.ROOT);
	}

	// ----------------------------------------------------------- shared: varps

	public int specPercentVarpId()
	{
		return varps().specPercentVarpId;
	}

	public int specEnabledVarpId()
	{
		return varps().specEnabledVarpId;
	}

	public int poisonVarpId()
	{
		return varps().poisonVarpId;
	}

	public int reportWidgetGroup()
	{
		return varps().reportWidgetGroup;
	}

	public int bankWidgetGroup()
	{
		return varps().bankWidgetGroup;
	}

	public int bankWidgetChild()
	{
		return varps().bankWidgetChild;
	}

	public int reportWidgetChild()
	{
		return varps().reportWidgetChild;
	}

	// -------------------------------------------------------------------- gear

	/**
	 * Every piece of gear that bypasses the magic-attack gate: the shared floor plus this god's own
	 * additions.
	 *
	 * <p>Same union as {@link #rangedWeapons()}, for the same reason - gear legal under every god is
	 * named once in {@code shared} rather than copied into four profiles that then drift apart.
	 */
	public String magicGearExceptions()
	{
		java.util.LinkedHashSet<String> all = new java.util.LinkedHashSet<>();
		collect(all, pack.shared == null ? null : pack.shared.gearExceptions);
		collect(all, active == null ? null : active.gear.magicGearExceptions);
		// shields are armour too: listed apart only so the plugin can tell them from other gear
		collect(all, pack.shared == null ? null : pack.shared.shields);
		collect(all, active == null ? null : active.gear.shields);
		return String.join(",", all);
	}

	/** Every shield the codex names, shared and this god's, as a comma-separated list. */
	public String shields()
	{
		java.util.LinkedHashSet<String> all = new java.util.LinkedHashSet<>();
		collect(all, pack.shared == null ? null : pack.shared.shields);
		collect(all, active == null ? null : active.gear.shields);
		return String.join(",", all);
	}

	/** Off-hand items that earn no block PKP, as a comma-separated list. */
	public String noBlockPkpItems()
	{
		return pack.shared == null ? "" : join(pack.shared.noBlockPkpItems);
	}

	/** Off-hand items that cost PKP on a block, as name:PKP-lost pairs. */
	public String blockPenaltyItems()
	{
		return pack.shared == null ? "" : joinPairs(pack.shared.blockPenaltyItems);
	}

	/** Per-shield PKP for a block, as name:PKP pairs. */
	public String shieldBlockPkp()
	{
		return pack.shared == null ? "" : joinPairs(pack.shared.shieldBlockPkp);
	}

	public String magicGearForceBlock()
	{
		return active == null ? "" : join(active.gear.magicGearForceBlock);
	}

	// ----------------------------------------------------------------- weapons

	/**
	 * Quest equipment, which overrides every other equipment rule.
	 *
	 * <p>Read from {@code shared}, so it survives states that have no active profile: with no god
	 * chosen nothing is restricted anyway, but the list still answers truthfully, and the side
	 * panel can show it without an oath in force.
	 */
	public List<ContentPack.QuestItem> questItems()
	{
		return pack.shared == null || pack.shared.questItems == null
			? java.util.Collections.emptyList()
			: java.util.Collections.unmodifiableList(pack.shared.questItems);
	}

	/**
	 * Every weapon barred under this god: the shared ban floor plus this god's own bans.
	 *
	 * <p>The one union that <em>subtracts</em>. The shared floor is a default rather than an
	 * absolute: a weapon on it is dropped for any god that names the same weapon in its own
	 * {@code weapons.weaponExceptions} or {@code ranged.rangedWeapons}, so a god lifts the
	 * floor by allowing the weapon rather than by editing the floor. That is how Zaros keeps the
	 * charged sceptres the other three are barred from without the staff list being copied into
	 * four profiles.
	 *
	 * <p>A god's <b>own</b> bans are not subtractable - they are added after the carve-out, so a
	 * profile that both bans and allows the same weapon bans it. A denial the god wrote itself
	 * outranks its own allow-list; otherwise authoring one would silently cancel the other
	 * depending on which list you edited last.
	 */
	public String blockedWeapons()
	{
		if (active == null)
		{
			return "";
		}
		java.util.Set<String> allowed = new java.util.HashSet<>();
		addLower(allowed, active.weapons.weaponExceptions);
		addLower(allowed, active.ranged.rangedWeapons);

		java.util.LinkedHashSet<String> all = new java.util.LinkedHashSet<>();
		List<String> floor = pack.shared == null ? java.util.Collections.<String>emptyList()
			: pack.shared.blockedWeapons;
		for (String s : floor)
		{
			if (s != null && !s.trim().isEmpty()
				&& !allowed.contains(s.trim().toLowerCase(java.util.Locale.ROOT)))
			{
				all.add(s.trim());
			}
		}
		collect(all, active.weapons.blockedWeapons);
		return String.join(",", all);
	}

	/** Only this god's own weapon bans, without the shared powered-staff floor. */
	public String godBlockedWeapons()
	{
		return active == null ? "" : join(active.weapons.blockedWeapons);
	}

	/** Lower-cased, blank-free view of a list, for the carve-out test above. */
	private static void addLower(java.util.Set<String> into, List<String> from)
	{
		if (from == null)
		{
			return;
		}
		for (String s : from)
		{
			if (s != null && !s.trim().isEmpty())
			{
				into.add(s.trim().toLowerCase(java.util.Locale.ROOT));
			}
		}
	}

	/**
	 * Every weapon exempt from the magic-attack gate: the shared floor plus this god's additions.
	 *
	 * <p>The third of the three unions, alongside {@link #rangedWeapons()} and
	 * {@link #magicGearExceptions()}, and for the same reason - a weapon legal under every god is
	 * named once in {@code shared} instead of copied into four profiles that then drift. The list
	 * also decides which weapons earn the exception PKP-per-hit.
	 */
	public String weaponExceptions()
	{
		java.util.LinkedHashSet<String> all = new java.util.LinkedHashSet<>();
		collect(all, pack.shared == null ? null : pack.shared.weaponExceptions);
		collect(all, active == null ? null : active.weapons.weaponExceptions);
		return String.join(",", all);
	}

	public int weaponExceptionDefaultPkp()
	{
		return active == null ? 0 : active.weapons.weaponExceptionDefaultPkp;
	}

	public String pkpWeapons()
	{
		return active == null ? "" : joinPairs(active.weapons.pkpWeapons);
	}

	// ------------------------------------------------------------------ ranged

	/**
	 * Every ranged weapon in force: the shared floor plus this god's own additions.
	 *
	 * <p>A union rather than an override in either direction, so a weapon legal for everyone is
	 * named once in {@code shared} and a god's list carries only what it adds. The shared half
	 * answers even with no god in force, which keeps the ranged PKP restore working before an oath
	 * is sworn.
	 */
	public String rangedWeapons()
	{
		java.util.LinkedHashSet<String> all = new java.util.LinkedHashSet<>();
		collect(all, pack.shared == null ? null : pack.shared.rangedWeapons);
		collect(all, active == null ? null : active.ranged.rangedWeapons);
		return String.join(",", all);
	}

	/** Adds the non-blank entries of a list, ignoring case-only repeats between the two sources. */
	private static void collect(java.util.LinkedHashSet<String> into, List<String> from)
	{
		if (from == null)
		{
			return;
		}
		for (String s : from)
		{
			if (s == null || s.trim().isEmpty())
			{
				continue;
			}
			String t = s.trim();
			boolean seen = false;
			for (String have : into)
			{
				if (have.equalsIgnoreCase(t))
				{
					seen = true;
					break;
				}
			}
			if (!seen)
			{
				into.add(t);
			}
		}
	}

